INSERT INTO "public"."lessons" ("title", "description", "content_type", "order_index", "estimated_duration_minutes", "is_previewable", "is_mandatory", "created_at", "updated_at", "slug", "id", "module_id", "book_id", "course_id") VALUES
	('سوالات آخر فصل 2', 'درآخر هر فصل، ابزار کانکور با طرح پرسش های مناسب و کاربردی، میزان یادگیری شما را ارزیابی می کند. پس با ثبت بهترین نمرات، با آمادگی کامل به فصل بعدی وارد شوید.', 'quiz', 999, 5, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth11_s2_6', 'ab1381bf-b35b-41ef-99cc-cca28404f62b', 'e910ffca-0dd5-459c-839c-4fb00bcfe352', '36cd2b47-9738-4991-a02d-e5392b1803f8', 'e127d1e6-d320-4973-9ced-5c5a1f8989d7'),
	('سوالات آخر فصل 5', 'بعد از آشنایی با نسبت های مثلثاتی، تبدیل مجموع به ضرب، و تبدیل ضرب به تفاضل،  طول قوس و مساحت قطاع دایره، دریافت ارتفاع، مساحت مربوط به دایره و ... از شما خواهشمندیم به سوالات طرح شده در همین رابطه پاسخ دهید.با آرزوی موفقیت برای شما.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth10_s5_9', 'cb3bd88a-4d73-49a7-9f5e-674e1c429ea3', '3ab76e58-3dd6-4efb-8d72-a17737939bd6', '2ceaac56-c15b-4f1b-a4db-7aa0f929a3f1', '7fa7f616-e4e5-454d-b029-c6629259e132'),
	('سوالات آخر فصل 7', 'در آخر این فصل هم با حل سوالاتی مناسب و مربوط با موضوع درسی این فصل، سطح یادگیری و ماندگاری مطالب را در ذهن خود بیشتر کنید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth10_s7_8', '2f32db03-48e5-4050-9be1-078fbf72167d', 'c18206b2-e866-4927-81f6-4639f6c2e6d4', '2ceaac56-c15b-4f1b-a4db-7aa0f929a3f1', '7fa7f616-e4e5-454d-b029-c6629259e132'),
	('سوالات آخر فصل 7', 'در آخر این فصل هم برای شما متعلمین گرامی سوالاتی در رابطه با  نرم تنان، حیوانات مفصلیه و حشراتی که در این فصل با آن ها آشنا شده اید طرح کرده ایم. امیدواریم به تمامی این سوالات پاسخ درست دهید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly11_s7_10', '4ccef8c6-2438-4a9f-b68c-0db478896ff9', 'f46540da-8d7b-4e35-9f32-96595677514e', 'e5a85c30-20cc-4b26-a305-ea62eea17489', '18995631-2d99-44ba-806b-e16abe3f18b1'),
	('سوالات آخر فصل 4', 'طبق معمول، در آخر این فصل هم با طرح پرسش های مناسب، میزان یادگیری خود را به چالش بکشید. ', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth11_s4_5', 'b2b437fd-edbe-4bde-bb3c-0fde4a4627d3', '85a498bb-1a35-41eb-99c5-f947e787257b', '36cd2b47-9738-4991-a02d-e5392b1803f8', 'e127d1e6-d320-4973-9ced-5c5a1f8989d7'),
	('سوالات آخر فصل 5', 'طبق معمول ابزار کانکور با طرح پرسش های مناسب و مفهومی می خواهد میزان یادگیری شما را ارزیابی کند و نکات جدیدی را در قالب حل سوالات به شما بیاموزد. پس با اشتیاق کامل به این سوالات بپردازید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth11_s5_7', '5074ea3d-ebf4-4266-a805-0a7df685bc74', '9064be15-35b1-4cf4-b4f4-bc37612f1d4d', '36cd2b47-9738-4991-a02d-e5392b1803f8', 'e127d1e6-d320-4973-9ced-5c5a1f8989d7'),
	('سوالات آخر فصل 6', 'برایتان سوالاتی بسیار مناسب طرح کرده ایم تا شما بتوانید فورمول ها و مطالبی را که آموخته اید به طور عملی در حل مسائل به کار ببندید. پس با حل این سوالات ریاضی را به طور عملی در حل مسایل به کار بگیرید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth11_s6_7', '58a22f9d-32c2-4c71-ae81-67451ab03282', '6b2cc07b-84e7-4bf7-8cea-856094628df0', '36cd2b47-9738-4991-a02d-e5392b1803f8', 'e127d1e6-d320-4973-9ced-5c5a1f8989d7'),
	('سوالات آخر فصل 8', 'فقط یک فصل تا آخرکتابتان باقی مانده است. با مطالعه کامل کتاب، خصوصا این فصل، خودتان را آماده امتحانات نهایی مکتب کنید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth11_s8_5', 'c459fb96-1f1c-46ea-9777-55789e10b008', '925e785b-ff28-43d9-837a-874c3629b58d', '36cd2b47-9738-4991-a02d-e5392b1803f8', 'e127d1e6-d320-4973-9ced-5c5a1f8989d7'),
	('سوالات آخر فصل 9', 'این فصل، آخرین فصل از کتابتان است که امیدواریم بتوانید با نمره های عالی هم این فصل و هم کل کتاب را به پایان برسانید. با آرزوی موفقیت شما و دیدارتان در سال آینده در صنف دوازدهم.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth11_s9_5', '4946f1b3-f9cf-4998-bf33-4ebeac62c7ed', '37257ab5-4813-4ccf-82f1-b3fde63304d8', '36cd2b47-9738-4991-a02d-e5392b1803f8', 'e127d1e6-d320-4973-9ced-5c5a1f8989d7'),
	('سوالات آخر فصل 3', 'به آخر فصل 3 رسیدیم. امیدوار هستیم تا این قسمت از کتاب را به خوبی درک کرده و فرا گرفته باشید. برای ارزیابی سطح خودتان می توانید به حل سوالات آخر این فصل بپردازید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs11_s3_5', 'c866f8f6-3ac7-4f24-9101-e513875a3c32', '317b77b6-8ef2-459a-8718-7c815b428b46', '2b87a5cc-20ab-4a7b-a823-763ee3da389d', '5c077f9f-19f4-4729-aefa-6f29e3002100'),
	('سوالات فصل 7', 'برایتان سوالاتی بسیار مناسب در رابطه با اجسام هادی و غیر هادی و نیز در رابطه با پیل ها آماده کرده ایم . هدف از طرح پرسش؛ افزایش مهارت شما در درک مطلب و نیز آموزش نکات جدید در حین حل کردن سوالات است. پس با اشتیاق کامل به حل این سوالات بپردازید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm11_s7_4', '723a4d7c-9ef2-4aa7-a629-3d498ee72776', '682a09d6-a0f1-468a-bb6f-236b9b3a7971', '44cdff31-b80f-46c6-bca1-5300913e7c71', 'a0d96968-6f92-4882-a988-95faaedc24b8'),
	('سوالات آخر فصل 1', 'بعد از تمام شدن فصل اول، حالا نوبت به حل سوالات آخر فصل آن می رسد. برای ورود به فصل 2 ابتدا این فصل را با نمرات عالی به پایان برسانید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'gpy10_s1_3', '101c316f-d905-4c16-82e7-e5bc83f49aa2', 'e0f30c85-0569-478b-859b-ace6f19d655e', '21717b1e-0026-4805-b9f6-4ebf08a1faf5', 'b2d9b6be-aa2e-4ddc-b004-8a59fbbefcaf'),
	('سوالات آخر فصل 2', 'بعد از اشنایی با اقلیم های مونسون، صحرایی، کوهستانی و ... باید بتوانید به سؤالات آخر فصل آن پاسخ مناسب بدهید. پس اول مرور فصل، سپس حل سوالات آن. در ادامه شما را به حل سوالات دعوت می کنیم.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'gpy10_s2_3', '22ab50c5-7593-48f0-a961-967ff07ef18d', 'f44afdc4-6801-4754-a355-c9274d69e3d6', '21717b1e-0026-4805-b9f6-4ebf08a1faf5', 'b2d9b6be-aa2e-4ddc-b004-8a59fbbefcaf'),
	('سوالات فصل 11', 'به سوالات آخرین فصل کیمیا رسیدیم. خیلی خوشحال هستیم که تا این لحظه همراه و یار شما بوده ایم. بعد از مرور دقیق فصل11 به حل سوالات آن اقدام کنید. کتاب را از اول تا به آخر آن بارها و بارها مرور کنید. در حل تست های آخر هر فصل مشاهده با دقت ویدیو ها کمک زیادی به شما خواهد کرد. ابزار کانکور با آرزوی پیشرفت هر روز شما، مشتاق دیدارتان در صنف 12 است. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm11_s11_2', 'a6b91c8b-87a6-4feb-9bd2-62e50810b905', 'ebbe2c8e-fac9-4c92-b61e-eda0d1b4d1bf', '44cdff31-b80f-46c6-bca1-5300913e7c71', 'a0d96968-6f92-4882-a988-95faaedc24b8'),
	('سوالات آخر فصل 5', 'بعد از آشنایی با عدسی ها و انواع آن، معادله مربوط به عدسیه ها و روش نیوتون در عدسیه ها، می خواهیم سوالاتی در همین رابطه از شاگردان باهوش و دانا پورسان کنیم.  پس آمادگی خود را برای خاتمه این فصل با گرفتن نمرات عالی نشان دهید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs10_s5_4', '7df94651-c320-4d42-b72c-98c00cc73ce3', '3f3b910d-d9e7-46a5-b84b-a38799d51213', '836e0039-81d6-4b5d-a26a-2cef99c64eaf', '96d9399f-2f03-4576-936d-9fa8d4c44fb2'),
	('جلسه 8', 'بررسی وضعیت زراعت و مالداری در افغانستان', 'video', 8, NULL, false, true, '2025-12-04 16:46:04.677854+00', '2025-12-07 18:55:59.234935+00', 'gpy11_s1_8', 'dc4d2359-e48b-4da3-9448-bb36b8c5a844', 'a9a06165-bb82-4ad3-b7b2-5aa0e13a54df', '9f0f9356-dca3-40c6-af89-00a297477275', 'c93560b5-2e32-4a19-96d2-43f23cd596fe'),
	('سوالات آخر فصل 6', 'حالا نوبت به پرسش های آخر این فصل در رابطه با ساختار اتوم، اندازه گیری چارج، طریق های اندازه گیری چارج و مباحثی است که در این فصل با آن ها آشنا شده اید. مثل همیشه اول به مطالعه کامل فصل پرداخته و سپس اقدام به حل سوالات آن نمایید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs10_s6_5', '1734e18b-3f85-4092-8453-cdeb2a13d065', 'a2cda5af-f504-4208-b1d8-03bcf57a86cc', '836e0039-81d6-4b5d-a26a-2cef99c64eaf', '96d9399f-2f03-4576-936d-9fa8d4c44fb2'),
	('سوالات آخر فصل 6', 'خب متعلمین عزیز می دانم که شما هم پیش خود می گویید فصل 6 طولانی و سخت بوده!!! اما زیاد تشویش نکنید چون هر درس سخت هم می تواند با تمرین و تکرار و حل سوالات مربوط، آسان و قابل فهم شود. پس مثل همیشه اول همین فصل را به دقت بخوانید سپس شروع به حل کنید. اگر سوالی را اشتباه حل نمودید از خود ناامید نشوید چرا که هر اشتباه نکته جدیدی به شما می آموزد. پس با آمادگی کامل شروع کنید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm10_s6_6', '77e6205f-1d9d-4377-a5c7-b658374cf8b3', '3f4570bc-097e-4dfa-b22e-14239a138014', '62adfbd4-1155-4b83-a065-21ebba9c5118', 'cd5ef238-334a-43bc-990c-05b56d89f2d5'),
	('سوالات آخر فصل 7', 'در این فصل با انواع تعاملات کیمیاوی و چند مثال در رابطه با آن ها آشنا شدید. یاد گرفتید چگونه تشخیص دهید که تعاملی از چه نوعی است یا اینکه آن ها رابیلانس کنید.انواع تعاملات رابه لحاظ انتقال گرما فرا گرفتید و طبق معمول حالا باید به سوالات آخر فصل آن پاسخ دهید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm10_s7_7', '67c8ed28-1c47-44f4-973b-28f6001b792d', '55f15fbb-a800-4e20-9b7a-0c13db66e9df', '62adfbd4-1155-4b83-a065-21ebba9c5118', 'cd5ef238-334a-43bc-990c-05b56d89f2d5'),
	('سوالات آخر فصل 8', 'دیگر چیزی تا اتمام این کتاب نمانده است. در این فصل شما با مفهوم اکسیدیشن و ریدکشن و چگونگی محاسبه نمبر اکسیدیشن آشنا شدید. امیدوار هستیم که تا به این لحظه از آموزش های داده شده استفاده کامل را برده باشید. در ادامه شما را به حل سوالات مرتبط و مناسب با این فصل دعوت می کنیم.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm10_s8_4', '1f2ccf85-3c26-4c60-9cb2-6657f83ead1a', '78fe6cbc-80f0-45ee-853f-c484376198a1', '62adfbd4-1155-4b83-a065-21ebba9c5118', 'cd5ef238-334a-43bc-990c-05b56d89f2d5'),
	('سوالات آخر فصل 8', 'بعد از اتمام فصل کوتاه و آسان هفتم، آیا آماده هستید تا به سوالات آن پاسخ دهید؟؟ از جواب بلی شما بسیار خرسند شدیم. پس برویم تا آن را هم حل کرده و تمام کنیم.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly10_s8_2', '0f90741b-284d-4bd8-ab25-627f9a03fcfe', '78577601-1a43-414f-a406-0f6cca13440a', 'f23aca64-2814-4041-a021-dc6e81f67d24', '9c980a0a-3f0b-4dd8-88a4-2a07c0ddea11'),
	('سوالات آخر فصل 9', 'به سوالات آخرین فصل بیولوژی خوش آمدید. بسیار خرسندیم که تا این لحظه همراه شما عزیزان بوده ایم. می خواهیم با ارائه پرسش های مفهومی و مناسب، آمادگی شما را برای اتمام این فصل و شروع امتحانات نهایی مکتب بیشتر کنیم. به امید دیدار شما در صنف یازدهم. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly10_s9_3', '7169c484-82c4-4534-9102-b535e5120bad', '3a46f1df-e882-47c7-85ef-042c06bf2974', 'f23aca64-2814-4041-a021-dc6e81f67d24', '9c980a0a-3f0b-4dd8-88a4-2a07c0ddea11'),
	('سوالات آخر فصل 1', 'متعلمین گرامی پس از آنکه تمام مطالب و نکات فصل اول را فراگرفتید، به سوالات آخر فصل آن پاسخ دهید. حل سوالات مناسب و مرتبط با مطالب آموخته شده می تواند ماندگاری آموخته ها را در ذهن شما بیشتر نموده و نیز نکات جدیدی به دانسته های شما اضافه کند.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm10_s1_6', '2b8cd64e-0fff-4ba8-8cc7-163bfc7563eb', '0a5bd1be-0023-4e8e-a074-8ed4d7206764', '62adfbd4-1155-4b83-a065-21ebba9c5118', 'cd5ef238-334a-43bc-990c-05b56d89f2d5'),
	('سوالات آخر فصل 2', 'بعد از آموزش مطالب و نکات مربوط به تغییرات شعاع اتومی، معرفی آیون ها و ... نوبت آن می رسد که شما سطح یادگیری خود را با حل چند سوال مناسب و مربوط امتحان و آزمایش کنید. پس ابتدا اول ویدیو ها و کتاب را به دقت مطالعه کنید و سپس شروع به حل سوالات آخر فصل کنید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm10_s2_3', '55ca21af-306b-4aeb-a166-e0523358b5f0', 'bef7d8b1-4b4d-4b09-8f90-dffa2b0c1071', '62adfbd4-1155-4b83-a065-21ebba9c5118', 'cd5ef238-334a-43bc-990c-05b56d89f2d5'),
	('سوالات آخر فصل 3', 'به سوالات آخر فصل سوم خوش آمدید. در این جا هم قصد داریم با طرح سوالاتی از متن کتاب و نیز مفاهیم مربوط به مطالب آموخته شده، سطح یادگیری شما متعلمین عزیز را بسنجیم. پس برای گرفتن نمره های بالا نخست فصل 3 را به دقت بخوانید سپس شروع به حل سوالات آن کنید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm10_s3_3', 'b8aecc56-d1bc-45e4-ac5a-20f15a898b81', '250b10bb-cbd1-4fa7-b91b-0ffd0842a370', '62adfbd4-1155-4b83-a065-21ebba9c5118', 'cd5ef238-334a-43bc-990c-05b56d89f2d5'),
	('سوالات آخر فصل 8', 'شاگردان عزیز به آخرین فصل ریاضی دوازدهم رسیده ایم. خیلی خوشحال هستیم که تا به این لحظه همراه شما بوده ایم. ابزار کانکور با هدف افزایش آمادگی شما برای کامیابی در کانکور، توصیه می کند ویدیو ها را چندین بار با دقت مشاهده کرده و در حین مشاهده از نکات مهم آن یادداشت برداری کنید. هیچگاه بخاطر اشتباه حل کردن مساله ها از خود ناامید نشوید بلکه با تلاش بیشتر و تمرین زیادتر، توانایی خود را بیشتر کنید. ابزار کانکور مشتاق موفقیت و سربلندی روز افزون شماست.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'mth12_s8_5', '166b17cc-92ed-4d9c-9618-3622aaf7a71b', '96233563-19d8-4e9b-b3d1-56186e271c28', 'b258ad30-4e1c-4028-9082-cf82157a7460', 'b484dd39-fc41-466d-9c82-5ed086cba8fd'),
	('سوالات آخر فصل 1', 'امیدوار هستیم که فصل اول را به خوبی آموخته باشید. ابزار کانکور با هدف کمک به افزایش ماندگاری مطالب در ذهن شما متعلمین عزیز، سوالاتی را جهت رسیدن به این هدف آماده نموده است. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly12_s1_9', '147c743f-b4d4-4121-90cb-89ab1cdd900a', '532bf180-80ae-4848-a1ed-993fcc67e39e', '9d2358da-ef85-4073-9610-bc5250e7d2a4', 'bec9a8b6-6678-4a0a-ac12-4abdef3040e6'),
	('سوالات آخر فصل 2', 'بعد از آشنایی با موضوعاتی نظیر موتیشن ها و تورنر سیندرم و ... با طرح سوالاتی در رابطه با موضوعات همین فصل، آمادگی شما را برای ورود به فصل بعد بیشتر می کنیم . موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly12_s2_4', 'fd0edcd4-543a-4d90-886e-074b2250221f', '9dbe5bd2-af82-4ec4-9c99-c68bd4c643a4', '9d2358da-ef85-4073-9610-bc5250e7d2a4', 'bec9a8b6-6678-4a0a-ac12-4abdef3040e6'),
	('سوالات آخر فصل 10', 'در این فصل هم با ساختمان کاربوکسیلیک اسید و  شیوه نامگذاری آن ها و ... آشنا شدید. در ادامه شما را به حل سوالات آخر این فصل دعوت می کنیم.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm12_s10_3', 'e3f94e11-8053-46a7-b7b2-80d6546e3398', 'd4359e3a-3f53-4f78-b771-e06c914588fa', 'bc254243-7623-49a0-9d8d-c570e5b409b8', 'ef570180-85f7-4649-a087-3c8e994b50ac'),
	('سوالات آخر فصل 3', 'در فصل سوم از کتاب بیولوژی خود با DNA و RNA آشنا شدید. همچنین موضوعاتی مثل تاریخچه انجینری جنیتیک، جن تخنیک در زراعت و ... برای شما بیان گردید. اگر تمام ویدیوهای این فصل را به طور کامل و دقیق مشاهده نموده اید به سوی حل سوالات آخر این فصل گام بردارید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly12_s3_6', '09818b0c-1f42-40ae-87cf-f53119bace26', '14fbcfff-6e41-4e6f-8a16-4e89134467ec', '9d2358da-ef85-4073-9610-bc5250e7d2a4', 'bec9a8b6-6678-4a0a-ac12-4abdef3040e6'),
	('سوالات آخر فصل 4', 'تبریک می گوییم که توانستید فصل بسیار  پر محتواو مطلب چهارم را به آخر برسانید. امیدواریم که ویدیو ها به طور کامل مشاهده و استفاده شده باشد. در این صورت قادر خواهید بود به تمام سوالات آخر این فصل پاسخ بدهید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly12_s4_9', 'd43e252a-dfd3-4062-b5ee-94e1320335e6', '70c6e99d-9ea7-4ac3-8c74-040f20f9c5b1', '9d2358da-ef85-4073-9610-bc5250e7d2a4', 'bec9a8b6-6678-4a0a-ac12-4abdef3040e6'),
	('سوالات آخر فصل 5', 'به آخر فصل پنجم از بیولوژی صنف دوازدهم رسیدیم. تا اینجا شما مطالب بسیار مفید در رابطه با سیستم داخلی بدن فراگرفته اید. آیا ویدیو ها را به طور کامل و دقیق مشاهده کرده اید؟ اگر بلی، به سوی حل سوالات آخر فصل آن گام بردارید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly12_s5_9', 'c5fbf7b2-7ea9-4970-87dd-87cb80705e30', '520f3e20-67cd-4ce6-a417-e6511afdfdac', '9d2358da-ef85-4073-9610-bc5250e7d2a4', 'bec9a8b6-6678-4a0a-ac12-4abdef3040e6'),
	('سوالات آخر فصل 10', 'به آخرین فصل از درس بیولوژی خوش آمدید. خیلی خوشحال و مفتخر هستیم که تا به این لحظه همراه شما بوده ایم. ابزار کانکور ضمن آرزوی موفقیت شما در امتحانات نهایی مکتب و کانکور، شما را به حل سوالات طرح شده  در آخر همین فصل دعوت می کنیم.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'bly12_s10_9', '5bab9176-5a72-4139-9bc2-ca8f18a1aace', '36dde002-75ac-46b6-9e45-2f826872f531', '9d2358da-ef85-4073-9610-bc5250e7d2a4', 'bec9a8b6-6678-4a0a-ac12-4abdef3040e6'),
	('سوالات آخر فصل 1', 'بعد از آشنایی با مفاهیمی مثل رقاصه ساده، معادله حرکت هارمونیکی، فریکونسی ساده و ... به چندس وال طرح شده در همین رابطه پاسخ دهید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs12_s1_4', '0bd37464-f4fc-4771-903e-e0ffbd9058af', '546abbaa-167f-4499-bf09-1475fa461cbc', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b', '32c42035-661d-440c-b939-a23bff4456ca'),
	('سوالات آخر فصل 2', 'بعد از مطالعه دقیق این فصل به حل سوالات آن اقدام کنید. وقتی شما با آمادگی کامل به حل سوال می پردازید قادر خواهید بود به بخش بیشتری از پرسش ها پاسخ دهید و این خود باعث افزایش انگیزه و اعتماد به نفس در شما متعلمین خواهد شد. با رعایت این موارد شروع به حل کنید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs12_s2_5', 'b0b5ecce-1725-4407-bd79-fe7a11e0a972', '806f1046-d07c-4828-9e37-ef0dc554ceb5', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b', '32c42035-661d-440c-b939-a23bff4456ca'),
	('سوالات آخر فصل 3', 'فصل 3 هم به اتمام رسید. آیا برای ورود به فصل 4 آمادگی دارید؟؟ پس به حل سوالات آخر این فصل هم بپردازید. پیشاپیش از نمرات عالی که بعد از حل سوالات آن کسب می کنید از شما متعلمین عزیز کمال تشکری و قدردانی را داریم. ', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs12_s3_3', 'c69d3445-90e1-4149-a9c3-5a6edf8a60a2', '0a65a7e9-a255-43ea-b949-3f12946c7e31', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b', '32c42035-661d-440c-b939-a23bff4456ca'),
	('سوالات آخر فصل 4', 'حرارت، درجه حرارت و جریان آن از جمله مباحث درس داده شده در فصل 4 بوده است. امیدوار هستیم که از بعد از تماشای ویدیو ها و مطالعه کتاب، نمرات کامل و عالی از حل سوالات طرح شده دریافت کنید. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs12_s4_5', '235d737b-cc9f-409f-8f26-0f20137fd790', '48978dbc-8cc6-45a8-a255-233ab2ef37dc', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b', '32c42035-661d-440c-b939-a23bff4456ca'),
	('سوالات آخر فصل 5', 'به آخر فصل 5 رسیدیم. فقط یک فصل تا انتهای کتاب باقی است. امیدوار هستیم که تا به این لحظه از ویدیو ها و آموزش ها استفاده کافی و کامل را برده باشید. مثل همیشه با طرح چند سوال، می خواهیم شما را برای ورود به فصل بعد آماده کنیم. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'phs12_s5_5', 'a5e2e707-2ae3-467a-aadd-77e00e04c7ed', 'f3aa2bf8-c2be-41e3-b668-963d16af3641', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b', '32c42035-661d-440c-b939-a23bff4456ca'),
	('سوالات آخر فصل 8', 'در آخر فصل 8 هم برای شما متعلمین عزیز سوالاتی مناسب و مرتبط با درس های این فصل آماده نموده ایم. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm12_s8_4', 'e93ed049-ef51-45f1-af4e-74f72a2eb15c', '5f7d62c7-9081-4fcf-88ea-ce2d27397db1', 'bc254243-7623-49a0-9d8d-c570e5b409b8', 'ef570180-85f7-4649-a087-3c8e994b50ac'),
	('سوالات آخر فصل 1', 'متعلمین عزیز بعد از یادگیری مفهوم هایبریدیزیشن، برای شما سوالاتی مرتبط با این موضوع آماده نموده ایم که می تواند به درک بهتر این مفهوم به شما کمک کند. موفق باشید.', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm12_s1_3', '670b548f-01e3-4129-a789-0badf9c25019', '5abef1d9-049f-4689-a0e1-57b1ed0616d1', 'bc254243-7623-49a0-9d8d-c570e5b409b8', 'ef570180-85f7-4649-a087-3c8e994b50ac'),
	('سوالات آخر فصل 9', 'کم کم به آخر فصل 9 نزدیک می شویم. مجددا شما را به حل سوالات آخر این فصل دعوت می کنیم .', 'quiz', 999, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 19:06:38.002091+00', 'chm12_s9_4', '97877ca1-8d1f-4602-953c-b1a843946e40', '8ab08151-261f-45bf-9e61-73a83079c84e', 'bc254243-7623-49a0-9d8d-c570e5b409b8', 'ef570180-85f7-4649-a087-3c8e994b50ac'),
	('جلسه 21', 'مقدمه، د متن لوستل، نوي لغاتونه، د کانکور پوښتنی.', 'video', 21, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 18:55:59.234935+00', 'pst11_21', 'd8b88f86-935b-4805-89cd-1fc2b26a51cb', 'aea7b915-511a-4a04-9f99-9e837d5b9f9a', 'a27be9ef-ed1d-4cf6-ab28-e9f85d5c8cab', '63b9e253-276c-44b3-b03d-27b4ff01d00b'),
	('جلسه 17', 'عوامل اعتیاد به مواد مخدر، رعایت نشانه گذاری در نگارش', 'video', 17, NULL, false, true, '2025-05-20 05:28:06.77549+00', '2025-12-07 18:55:59.234935+00', 'dri10_17', '84a9f049-b397-4bf7-b393-e4402c0f1ff4', '3716f89d-1bab-42f5-abe6-bed514371407', '160a155e-26d3-4b1e-87e5-45061140b905', '51897bdd-97a5-40c1-8ceb-57d395390710'),
