INSERT INTO "public"."lesson_content_blocks" ("block_type", "order_index", "text_content", "video_url", "video_provider", "video_transcript", "audio_url", "audio_transcript", "document_url", "external_resource_url", "external_resource_title", "code_language", "default_code", "solution_code", "image_url", "created_at", "updated_at", "id", "lesson_id", "playlist", "slug") VALUES
	('video', 0, 'مراحل میتودهای علمی تحقیق را می آموزیم، سوال طرح می کنیم، فرضیه می سازیم، تحلیل می کنیم و نتیجه می گیریم و راپور تهیه می کنیم', 'https://youtube.com/watch?v=rRiwORD0Wjc', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '86b06daa-0bf1-4dd6-b430-4770dbde4f8b', '211094b0-8e9f-4ba2-8d8c-8f880e808a85', NULL, 'bly10_s1_1'),
	('video', 0, 'آشنایی باعملیه متابولیزم، مشخصات مواد غیر عضوی،
اهمیت موجودیت آب و منرال ها ', 'https://youtube.com/watch?v=eerymtXWBSE', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '37d964a9-af59-4c32-aab8-5f9c426c3969', '86760c3a-6102-4314-8a38-2096d90732ec', NULL, 'bly10_s2_1'),
	('video', 0, 'آشنایی با انواع منرال ها، تاثیر برخی منرال های مهم در بدن، شناسایی منابع در دسترس منرال های مهم، 
نقش مرکبات غیر عضوی در متابولیزم نباتات را مطالعه می کنیم. ', 'https://youtube.com/watch?v=XAzva_UauTo', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', 'db9ba150-12f9-4f40-8732-d3235a46e545', 'ace30cf1-2ba2-4535-bd77-0718ca5a9b76', NULL, 'bly10_s2_2'),
	('video', 0, 'ساختمان و وظایف مواد عضوی، با انواع قند ها و موجودیت آن ها در غذاهای مختلف، آشنایی با پروتین و اجزا و انواع آن', 'https://youtube.com/watch?v=8n8anqVBMgo', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '0b4bcf14-5b25-4879-ad4e-0b30d8bf8520', '70ed142d-ad58-491d-9674-37b055a5e188', NULL, 'bly10_s3_1'),
	('video', 0, 'آشنایی با شحمیات، آشنایی با انزایم ها به عنوان کتالیست های عضوی، بررسی ویژگی های تیزاب های هستوی، بررسی نقش مرکبات عضوی در متابولیزم', 'https://youtube.com/watch?v=ukjE59wfZec', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '90a8fe38-e1d8-48f6-bde3-e6c9c8b3a758', '53d70fc2-35c8-4e64-8e92-a88d752f91c5', NULL, 'bly10_s3_2'),
	('video', 0, ' آشنایی با باکتریا و انواع آن، بررسی وایروس ها، فنجی، و پروتستا ها، آشنایی با بعضی امراض حاصل از میکروب، شناختن امراض ساری و غیر ساری  ', 'https://youtube.com/watch?v=5YyoaJhm2XE', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '0375f857-a941-42cb-a33f-66a98f03dc79', '1a358253-85b3-499c-b9d8-06b8fbc404c8', NULL, 'bly10_s4_1'),
	('video', 0, ' آشنایی با  سیستم های دفاعی بدن، بررسی جلد و غشاهای مخاطی در دفاع غیر اختصاصی، آشنایی با دفاع غیر اختصاصی و نحوه عمل واکسین
 آشنایی با سرطان. ', 'https://youtube.com/watch?v=Sthg10tKR8U', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '66897f6d-8ff2-4b3a-84cf-c35717e6b8c4', 'eaa967d5-1962-448a-9f37-78ef36ac17df', NULL, 'bly10_s4_2'),
	('video', 0, 'تعریف علمی غذا، نقش ویتامین ها در بدن و انواع آن، بررسی بعضی از ویتامین های ضروری بدن', 'https://youtube.com/watch?v=iecmsxx6pRU', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '68e4e498-6573-4008-a9a3-88404e18da9f', 'bf517aa0-5e45-4078-a51c-c334864c3fe9', NULL, 'bly10_s4_3'),
	('video', 0, 'آشنایی با دواها و انواع آن، آشنایی با ضددردها و انواع آن', 'https://youtube.com/watch?v=UTTefo9F7qU', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '3ef99946-f40b-4d5c-b7b9-9d69a0182227', 'cbddf576-cce4-4aa1-908b-0d154aabdf19', NULL, 'bly10_s4_4'),
	('video', 0, 'آشنایی با مفهوم و تاریخچه جنتیک، بررسی اهمیت علم جنتیک', 'https://youtube.com/watch?v=JwkmEY7K9G8', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '9b55a2a5-1597-47eb-b115-421939ba7c9d', 'b40f42c5-93ff-4f7b-b8e0-d46e37808bef', NULL, 'bly10_s5_1'),
	('video', 0, 'تجربیات مندل، بررسی آزمایشات مندل، آشنایی با تیوری مندل', 'https://youtube.com/watch?v=9CYaI52Wp8g', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', 'b4a30ee3-809a-44b2-b593-d2020c1f48b6', '2cde5a6c-3862-40a5-a8ed-7fd8279beca2', NULL, 'bly10_s5_2'),
	('video', 0, 'آشنایی با مربع پونت و نحوه ی کار با آن، آشنایی با کروموزوم، آشنایی با جن', 'https://youtube.com/watch?v=WXZEzSwi__Y', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '02acd501-39ff-4711-80d4-f7e8a0217577', 'd88ff1d5-8ed8-45c4-af18-fb76edc23d7c', NULL, 'bly10_s5_3'),
	('video', 0, 'آشنایی با شجره نامه جنتیکی، بررسی فنوتایپ نیمه بارز، بررسی اثر محیط بالای اثر جن', 'https://youtube.com/watch?v=FXRS2InOiH0', 'youtube', NULL, NULL, NULL, NULL, NULL, NULL, 'fa', NULL, NULL, NULL, '2025-12-04 16:37:22.752394+00', '2025-12-04 16:38:42.423973+00', '5d296bc1-c477-460a-9e9e-1958f3351672', '7f3ad7e5-9883-4e18-81a8-7d99070c063d', NULL, 'bly10_s6_1'),
