	('نسب نامه ارثی یا شجره نامه جنتیکی به کدام نام ذیل یاد میشود؟', 'برای بررسی چگونگی به ارث رسیدن صفت خاص باید از نسب نامه ارثی یا شجره نامه جنتیکی که به نام Pedigree یاد می شود.', NULL, 73, NULL, '{"{\"answer\": \"Genotype\", \"isCorrect\": false}","{\"answer\": \"Homozygous\", \"isCorrect\": false}","{\"answer\": \"Phenotype\", \"isCorrect\": false}","{\"answer\": \"Pedigree\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '4b890887-fafa-4250-b6f8-3224ad92b2cb', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('اگر خاصیت غالب بودن را در نظر بگیریم فردی که هتروزایگوس است و شخصی که هوموزایگوس است دارای کدام فنوتایپ می باشد؟', 'اگر خاصیت غالب بودن را در نظر بگیریم فردی که هتروزایگوس است و شخصی که هوموزایگوس  غالب است میتوانند فنوتایپ مشابه داشته باشند.و با کسی که هموزایگوس مغلوب است قطعا متفاوت خواهد بود ', 'هتروزایگوس Aaاست وفنوتایپ غالب را نشان میدهد هوموزایگوس غالبAA هم فنوتایپ غالب را نشان میدهد اما هوموزایگوس مغلوب aaصفت مغلوب را نشان میدهد ', 74, NULL, '{"{\"answer\": \"متفاوت \", \"isCorrect\": false}","{\"answer\": \"مشابه \", \"isCorrect\": false}","{\"answer\": \"هیج کدام \", \"isCorrect\": false}","{\"answer\": \"مشابه و متفاوت \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'c584b67c-0063-4748-a2c0-fe4c2c99d4de', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('یک انسان مؤنث در حجره جنسی خوددارای کدام  کروموزوم می باشد؟', 'تعداد کروموزوم ها در انسان 23 جوره میباشد که از جمله 22 جوره آنها کروموزوم های جسمی و یک جوره آن کروموزوم جنسی می باشد که تعیین کننده جنسیت در انسان است. اگر یک انسان مؤنث باشد یک جوره کروموزوم آن X,X می باشد.', NULL, 70, NULL, '{"{\"answer\": \"X، Y\", \"isCorrect\": false}","{\"answer\": \"Y ،Y\", \"isCorrect\": false}","{\"answer\": \"Y ،X\", \"isCorrect\": false}","{\"answer\": \"X، X\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'a5686181-1e89-4734-b13c-592d5e1e3aa2', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('اگر گامیت مؤنث X (مادر) با گامیت مذکر X (پدر) یکجا شود کدام جنس به وجود می آید؟', 'جنس مونث دو کروموزوم X دارد که تنها یک نوع گامیت تولید مینماید.اگر گامیت X مونث (مادر) با گامیت X مذکر(پدر) یکجا شود جنس مونث به وجود می آید.', NULL, 70, NULL, '{"{\"answer\": \"جنس مذکر\", \"isCorrect\": false}","{\"answer\": \"جنس خنثی\", \"isCorrect\": false}","{\"answer\": \"هیج کدام \", \"isCorrect\": false}","{\"answer\": \"جنس مؤنث\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '8c7c7591-dfbf-46ad-9202-da4e3259b4b2', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('حالت اوسط یا سومی نشان دهنده آنست که صفات والدین کاملا ........... نبوده اند؟', 'زمانیکه صفات به شکل نیمه بارز انتقال کنند فنوتایپ شخص هتروزایگوس حالت وسطی دو صفت خالص را اختیار می کند. حالت اوسط یا سومی نشان دهنده آنست که صفات والدین کاملاغالب  نبوده اند.', NULL, 74, NULL, '{"{\"answer\": \"مغلوب\", \"isCorrect\": false}","{\"answer\": \"هم غالب و هم مغلوب\", \"isCorrect\": false}","{\"answer\": \"نه غالب و نه مغلوب\", \"isCorrect\": false}","{\"answer\": \"غالب\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '81b6d837-0797-4177-8dff-647d3854daf5', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('جین های وابسته به جنس را کدام عالم کشف کرد؟', 'توماس مورگان با تحقیق درباره صفات مربوط به کروموزوم های جنسی مگس میوه، جین های وابسته به جنس را کشف کرد.', 'جن های وابسته به جنس آن دسته از صفاتی هستند که جن آن بر روی کروموزوم های جنسی قرار دارد و مذکر یا مونث بودن فرد در انتقال صفت اثر میگذارد ', 75, NULL, '{"{\"answer\": \"مندل\", \"isCorrect\": false}","{\"answer\": \"ستن\", \"isCorrect\": false}","{\"answer\": \"ولسن\", \"isCorrect\": false}","{\"answer\": \"توماس مورگان\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '2c9bebd2-5c7c-4e88-8890-81eec9e3451d', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('در کدام سال توماس مورگان در باره صفات مربوط به کروموزوم های جنسی مگس میوه تحقیق کرد؟', 'در سال 1910 توماس مورگان درباره صفات مربوط به کروموزوم های جنسی مگس میوه تحقیق کرد.', 'در مگس میوه جن های رنگ چشم بر روی کروموزوم X قرار دارد ورنگ چشم سفید که مغلوب است در مگس مونث با دو Xمغلوب ودرمگس مذکر با یکXمغلوب ظاهر میشود ', 75, NULL, '{"{\"answer\": \"1905\", \"isCorrect\": false}","{\"answer\": \"1984\", \"isCorrect\": false}","{\"answer\": \"1884\", \"isCorrect\": false}","{\"answer\": \"1910\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'e2714ed6-cafb-4517-9a28-db0de6c1eb9c', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
