	('برای انجام عملیه میتابولیزم حجره کدام مواد و مرکبات ضروریست ؟', 'برای انجام عملیه میتابولیزم حجره آب و مواد معدنی ضروری می باشد.', 'متابولیزم بالای ترکیبات عضوی عمل میکنند اما در کنار مرکبات عضوی به آب ومنرال ها وویتامین ها ضرورت دارد ', 12, NULL, '{"{\"answer\": \"منرال ها \", \"isCorrect\": false}","{\"answer\": \"آب \", \"isCorrect\": false}","{\"answer\": \"مواد معدنی \", \"isCorrect\": false}","{\"answer\": \"آب و مواد معدنی یا منرال ها \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'e567faee-1024-4cb2-b929-b27377eeaca4', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('مشنگ دارای یکی از مشخصات ذیل می باشد؟', 'مشنگ چند مشخصه دارد که هر کدام فقط دو حالت را نشان می دهد:رنگ گلبرگ آن ارغوانی یا سفید است و شکل دانه های آن چلمک یا صاف است و توانایی گرده افشانی خودی را دارد.', NULL, 56, NULL, '{"{\"answer\": \"گلبرگ ارغوانی یا سفید دارد\", \"isCorrect\": false}","{\"answer\": \"شکل دانه های آن چملک یا صاف است\", \"isCorrect\": false}","{\"answer\": \"توانایی گرده افشانی خودی دارد \", \"isCorrect\": false}","{\"answer\": \"گلبرگ ارغوانی یا سفیددارد،شکل دانه های آن چملک یا صاف است ،توانایی گرده افشانی خودی دارد \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'fc4b23e5-feec-45a8-a06b-d820f35496b5', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('نام سنگ معدنی  Fe₂O₃ عبارت است از:', 'فلز آهن از دو سنگ معدنی آن یعنی هماتیت (Fe₂O₃)و مگنیتایت (Fe₃O₄) به دست می آید.', NULL, 184, NULL, '{"{\"answer\": \"کورندوم\", \"isCorrect\": false}","{\"answer\": \"مگنیت\", \"isCorrect\": false}","{\"answer\": \"پیریتت\", \"isCorrect\": false}","{\"answer\": \"هماتیت\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'b3763089-d472-4b3b-be43-9026240661dd', 'cba94f01-9816-47bb-a8ad-9100133ab6f6', '44cdff31-b80f-46c6-bca1-5300913e7c71'),
	('اگر ممکن باشد یک عمل اتفاق بیفتد احتمال آن را به کدام یک از اشکال ذیل می نویسیم؟', 'اگر ممکن باشد که یک عمل اتفاق بیفتد احتمال آن را می توانیم به این صورت بنویسیم: به شکل عددی 1 از 1 ، به شکل فیصدی 100% ', NULL, 68, NULL, '{"{\"answer\": \"1 از 1\", \"isCorrect\": false}","{\"answer\": \"100%\", \"isCorrect\": false}","{\"answer\": \"0%\", \"isCorrect\": false}","{\"answer\": \"1 از 1 ویا100%\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '99b64043-41da-4454-b9ec-e8f287623e3c', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('انجینیران جنیتک می توانند یکی از تغییرات ذیل را در نباتات به وجود بیاورد؟', 'انجنیران جنتیک میتوانند تغییرات زیادی در نباتات به وجود بیاورند آنها میتوانند نباتات را در برابر خشکسالی مقاومتر بسازند و حتی میتوانند یک نبات را طوری تغییر دهند که هر نوع اقلیم ،خاک و محیط های متفاوت سازگار شوند.', ' چون گیاهان منبع اصلی غذای انسان را تشکیل میدهند انجینیران جنتیک تلاش های زیادی برای تولید نباتات با کیفیت بالاترغذایی ومقاومت بیشتر دارند', 89, NULL, '{"{\"answer\": \"مقاوم ساختن نبات در مقابل خشکسالی\", \"isCorrect\": false}","{\"answer\": \"سازگار ساختن آن با هر نوع قاره \", \"isCorrect\": false}","{\"answer\": \"برگ سبز\", \"isCorrect\": false}","{\"answer\": \" مقاوم ساختن نبات در مقابل خشکسالی ،سازگار ساختن آن با هر نوع قاره \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '3276f256-534d-4efe-9ae1-6fd0c29440e7', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('بزرگ شدن غده تایراید یا مرض جاغور قلت یکی از عناصر ذیل را نشان میدهد؟', 'در اثر کمبود ایودین غده تایراید فعالیت بیشتری می نماید تا جهت رفع ضرورت بدن ایودین بیشتری جذب کند  در نتیجه غده تایراد بزرگ ومتورم  میشود وبه نام بیماری گواتر یا جاغور یاد میشود ', 'کمبود ایودین  در مرض جاغور باعث کاهش فعالیت های بدن وایجاد حالت افسردگی در انسان میشود به همین دلیل در بعضی مناطق به نام غم باد شناخته میشود ', 17, NULL, '{"{\"answer\": \"کلسیم\", \"isCorrect\": false}","{\"answer\": \"سودیم\", \"isCorrect\": false}","{\"answer\": \"آهن\", \"isCorrect\": false}","{\"answer\": \"آیودین\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '269e6ed9-9323-40fe-93f9-7e51e5af48d0', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کدام یکی از قندهای ذیل از جمله قندهای دای سکراید است ؟', 'قندها یا کاربوهایدریت ها به انواع مختلف پیدا میشوند سکروز از جمله قند های دای سکراید است.', 'دای سکراید ها داری دو واحد قندی هستند که ومعولا شیرین مزه میباشند نیشکر لبلبو ولاکتوز قند شیر ومالتوز قند گندم وجو از جمله دای ساکراید ها هستند ', 20, NULL, '{"{\"answer\": \"فرکتوز\", \"isCorrect\": false}","{\"answer\": \"سلولوز\", \"isCorrect\": false}","{\"answer\": \"نشایسته\", \"isCorrect\": false}","{\"answer\": \"سکروز\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'f2d98f52-be38-4046-9bc3-7cad4d1993cf', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کدام یک از کاربوهایدریت های ذیل از جمله پولی سکراید ها نیست ؟', 'گلایکوجن ،نشایسته، سلولوز همه پولی سکراید هستند ولی فروکتوز مونو سوکراید است ', 'فروکتوز قند میوه است وشیرینی میوه ها به خاطر آن میباشد ', 20, NULL, '{"{\"answer\": \"گلایکوجن\", \"isCorrect\": false}","{\"answer\": \"سلولوز\", \"isCorrect\": false}","{\"answer\": \"نشایسته \", \"isCorrect\": false}","{\"answer\": \"فروکتوز\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '32e0e9fa-4eb0-41c4-9292-2fc320b1e675', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کدام ویتامین در سلامتی جلد رول مهمی ندارد؟', 'ویتامین C در سلامتی جلد ضرورت دارد.و ویتامین A وویتامین E به سلامت جلد کمک میکند ', 'ویتامین C منحل در آب است وحتما باید در غذا باشد ولی ویتامین AوE گاهی به صورت پماد ومواد آرایشی برای تقویت جلد کار گرفته میشود ', 48, NULL, '{"{\"answer\": \"ویتامین C\", \"isCorrect\": false}","{\"answer\": \"ویتامین E\", \"isCorrect\": false}","{\"answer\": \"ویتامین A\", \"isCorrect\": false}","{\"answer\": \"ویتامین k\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '4a778a1e-e294-4d6f-879f-148ebd5541a7', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('در اثر فقدان یکی از ویتامین های ذیل لخته شدن خون به قسم نورمال آن صورت نمی گیرد؟', 'در اثر فقدان ویتامین K در وقت لخته شدن خون به قسم نورمال صورت نمیگیرد.', 'لخته شدن خون در هنگام جراحت وخونریزی از کاهش ناگهانی حجم خون جلوگیری میکند', 48, NULL, '{"{\"answer\": \"ویتامین D\", \"isCorrect\": false}","{\"answer\": \"ویتامین A\", \"isCorrect\": false}","{\"answer\": \"ویتامین B3\", \"isCorrect\": false}","{\"answer\": \"ویتامین k\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'b955c4b2-8d0c-4eee-ac8b-67ec7a1d73ce', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کروموزوم از چه ساخته شده است؟', 'کروموزوم از پروتین و DNA ساخته شده است.', 'DNAماده اصلی جنتیکی است و بسیار طویل و بلند میباشد وبه دور مالیکول های پروتینی به نام هیستون پیچ وتاب میخورد ', 84, NULL, '{"{\"answer\": \"پروتین وشحم \", \"isCorrect\": false}","{\"answer\": \"DNAوشحم\", \"isCorrect\": false}","{\"answer\": \"DNAوقند \", \"isCorrect\": false}","{\"answer\": \"پروتین وDNA\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '5d336dfa-d6cf-40d0-ae1f-04e6ed529878', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کلسیم در یکی از ساختمان های ذیل حیوانات یافت میشود ؟', 'اساسأ کلسیم در بدن حیوانات و انسان ها در ساختمان استخوان ها و دندان یافت می شود.', NULL, 16, NULL, '{"{\"answer\": \"حجرات سرخ خون \", \"isCorrect\": false}","{\"answer\": \"غده تایراید  \", \"isCorrect\": false}","{\"answer\": \"جلد\", \"isCorrect\": false}","{\"answer\": \"دندان \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '3938479a-48c4-43ba-bfb1-e19a75c89d29', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('یک انسان بالغ که اندام متوسط داشته باشد تقریبا چند کیلوگرام کلسیم در بدن خود دارد؟', 'کلسیم منرالی است که به مقدار زیاد دربدن انسان وجود دارد. یک انسان بالغ که اندام متوسط داشته باشد تقریبا نیم کیلو گرام کلسیم در بدن خود دارد.', 'کلسیم جزء اولین موادی  است که در بدن ذخیره سازی  ان شروع میشود وبه همین دلیل غذای اولیه نوزادان شیر است و اولین مکان ذخیره سازی کلسیم استخوان است ', 16, NULL, '{"{\"answer\": \"دو کیلو گرام\", \"isCorrect\": false}","{\"answer\": \"سه کیلو گرام\", \"isCorrect\": false}","{\"answer\": \"چهار کیلو گرام\", \"isCorrect\": false}","{\"answer\": \"یک کیلو گرام\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '55b09ba4-e9be-4748-876f-1c8d484dc349', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کمبود کدام یکی از عناصر ذیل در اطفال باعث نرمی استخوان و در کلان سالان سبب پوکی استخوان می شود؟', 'کلسیم در محکم شدن استخوان ها نقش دارد .کمبود آن در اطفال باعث نرمی استخوان(راشیتیسم) و در کلان سالان سبب پوکی استخوان میشود.', 'در مادرانی که بارداری پشت سر هم دارند کلسیم از بدن مادر برداشت وبه بدن جنین داده میشود برای همین بافت استخوان سست وخالی از کلسیم شده واین مادران استخوان دردی وپای دردی زیادی راتحمل میکنند این استخوان های پوک شده به اسانی میشکند وگاهی اصلا درمان نمی شود ', 16, NULL, '{"{\"answer\": \"آهن\", \"isCorrect\": false}","{\"answer\": \"فاسفورس\", \"isCorrect\": false}","{\"answer\": \"سودیم \", \"isCorrect\": false}","{\"answer\": \"کلسیم\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '476dc899-b56b-404f-b961-4c50621b4142', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('اصطلاح راشیتیسم یکی از مفهوم ذیل را ارایه می دارد؟', 'اصطلاح راشیتیسم به نرمی استخوان گفته میشود که بدلیل کمبود کلسیم در زمان تشکیل بافت استخوان یعنی کودکی نوزادی وجنینی اتفاق می افتد', NULL, 16, NULL, '{"{\"answer\": \"پوکی استخوان\", \"isCorrect\": false}","{\"answer\": \"خورد شدن استخوان\", \"isCorrect\": false}","{\"answer\": \"کلان شدن استخوان\", \"isCorrect\": false}","{\"answer\": \"نرمی استخوان\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'ae53f2fc-76f2-4800-aa26-3b8a10a9b0f4', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('پاسخ های احتمالی به سوالاتی که از مشاهده نزد شما پیدا می شود عبارت از؟', 'وقتی به یک سوال با حدس وگمان پاسخ میدهیم در حالیکه ان گمان بر پایه مشاهده ومطالعه است یک فرضیه علمی ساخته ایم ', 'فرق فرضیه با بقیه حدس وگمان ها این است که بعد از مشاهده وتحقیق به ذهن می اید وحتما باید قابل ازمایش باشد ', 5, NULL, '{"{\"answer\": \"مشاهده\", \"isCorrect\": false}","{\"answer\": \"تهیه راپور\", \"isCorrect\": false}","{\"answer\": \"طرح سوال\", \"isCorrect\": false}","{\"answer\": \"فرضیه سازی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'ce0c3b79-296f-483c-8a58-413370f88426', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کمبود کلسیم در اطفال سبب عوارض ذیل میگردد؟', 'کمبود کلسیم در اطفال باعث بیماری راشیتیسم یا نرمی استخوان میگردد.', 'نوزاد با استخوان های نرم غضروفی به دنیا می اید و با چذب کلسیم استخوان ها محکم می شود کمبود کلسیم در کودکی باعث میشود استخوان نتواند کلسیم کافی جذب کند در نتیجه استخوان نرم ونیمه غضروفی باقی میماند ودر اثر افزایش وزن کودک کج میشود ', 16, NULL, '{"{\"answer\": \"کم اشتهایی\", \"isCorrect\": false}","{\"answer\": \"انقباض عضلات\", \"isCorrect\": false}","{\"answer\": \"کم خونی\", \"isCorrect\": false}","{\"answer\": \"راشیتیسم\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '8bef5acc-56b6-48ff-a671-b6d462e3bec3', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('مقدار فاسفورس در بدن هر انسان بالغ به اندازه ذیل می باشد ؟', 'فاسفورس نیز عنصری است که در بدن انسان مقدار فراوانی وجود دارد هر انسان بالغ به اندازه نیم کیلوگرام  فاسفورس در بدن خود دارد.', NULL, 16, NULL, '{"{\"answer\": \"یک کیلو گرام\", \"isCorrect\": false}","{\"answer\": \"دو کیلو گرام \", \"isCorrect\": false}","{\"answer\": \"یک و نیم کیلو گرام\", \"isCorrect\": false}","{\"answer\": \"نیم کیلو گرام\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '53a45bd9-3a4d-45f6-a676-681bfc61853b', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('مرض جاغور از کمبود ...... به وجود می آید؟', 'آیودین از جمله مواد غیر عضوی کم مصرف در بدن است. کمبود آیودین مرض جاغور(Goiter) به جود می آید.', 'در صورت کمبود آیودین غده تایراید فعالیت بیشتر مینماید تاجهت رفع ضرورت بدن آیودین بیشتر را جذب کندکه درنتیجه غده تایراید بزرگ شده و گلو متورم می شود .', 17, NULL, '{"{\"answer\": \"فاسفورس\", \"isCorrect\": false}","{\"answer\": \"آهن\", \"isCorrect\": false}","{\"answer\": \"سودیم \", \"isCorrect\": false}","{\"answer\": \"آیودین\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '2e0ef219-fb31-4b2c-a154-28eff99f1d89', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('در صورت کمبود آهن قدرت انتقال اکسجن درخون ....... می شود؟', 'هموگلوبین پروتین آهن دار است که در حجرات سرخ خون بوده و مسؤلیت انتقال آکسینجن را به تمام بدن دارد.در صورت کمبود آهن،قدرت انتقال اکسیجن کاهش میابد.', 'اکسیجن به اهن متصل میشود ودر خون جا به چا میشودبیشتر اکسیجن شش به صورت اتصال با اکسیجن به حجرات بدن میرسد ', 16, NULL, '{"{\"answer\": \"زیاد\", \"isCorrect\": false}","{\"answer\": \"تغییر نمی کند\", \"isCorrect\": false}","{\"answer\": \"هیج کدام \", \"isCorrect\": false}","{\"answer\": \"کم\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'f78311fd-b638-4173-b06c-6046d805b4b7', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('30 گرام تیزاب سرکه در 300 گرام آب حل گردیده است. غلظت مولل آن را دریافت کنید.(کتله مالیکولی تیزاب سرکه 60 گرام بر مول است).', NULL, NULL, 15, NULL, '{"{\"answer\": \"0.6 molal\", \"isCorrect\": false}","{\"answer\": \"1.8 molal\", \"isCorrect\": false}","{\"answer\": \"0.2 molal\", \"isCorrect\": false}","{\"answer\": \"     1.66 molal\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'f24afbc1-d622-49e9-94a5-6cfd84dd2eca', 'cba94f01-9816-47bb-a8ad-9100133ab6f6', '44cdff31-b80f-46c6-bca1-5300913e7c71'),
	('فلورین در کدام قسمت دندان موجود است؟', 'فلورین در ساختمان دندان ها بخصوص مینای دندان موجود است.', 'فلورین در ترکیب کریم های دندان علاوه می شود تا دندان ها سالم بمانند و از سوراخ شدن آنها جلوگیری گردد. ', 17, NULL, '{"{\"answer\": \"ثنایای دندان\", \"isCorrect\": false}","{\"answer\": \"ریشه دندان\", \"isCorrect\": false}","{\"answer\": \"دندان بالا\", \"isCorrect\": false}","{\"answer\": \"مینای دندان \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'feb78f04-6d2b-456d-b3e2-7e8fcec97a6d', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کدام یکی از عناصر ذیل در ساختمان کلوروفیل نباتات شامل است؟', 'مگنیزیم در ساختمان کلوروفیل نباتات شامل است.', 'کلوروفیل در کلوروپلاست های نباتات موجود بوده و عملیه فوتوسنتیز را در نباتات پیش میبرد.', 17, NULL, '{"{\"answer\": \"فلورین\", \"isCorrect\": false}","{\"answer\": \"سودیم\", \"isCorrect\": false}","{\"answer\": \"کلورین\", \"isCorrect\": false}","{\"answer\": \"مگنیزیم\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '4643c995-e079-412a-a657-c0a6c9c8e424', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('رول و اهمیت عنصر آهن در وجود انسان عبارت است از ؟', 'آهن موجود در ساختمان حجرات سرخ خون برای گرفتن اکسیجن هوا در شش ها و انتقال آن به دیگر قسمت های بدن رول مهم دارد.', 'کرویات سرخ خون صفحات دمویه وحجرات سفید هم در مغز استخوان ساخته میشوند ودر پلازمای خون شناور میباشند وهمه انها باهم به نام خون شناخته میشوند ولی فقط در ساخته شدن کرویات سرخ خون اهن کار گرفته میشود ', 17, NULL, '{"{\"answer\": \"در ساختمان صفحات دمویه \", \"isCorrect\": false}","{\"answer\": \"در ساختمان حجرات سفید خون \", \"isCorrect\": false}","{\"answer\": \"همه درست است\", \"isCorrect\": false}","{\"answer\": \"در ساختمان کرویات سرخ خون \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'c4778947-6517-436e-8007-bfb61c2a7990', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('مواد که در تعاملات حیاتی حجره تولید انرژی می کند به کدام نام یاد می شود؟', 'موادیکه در تعاملات حیاتی حجروی تولید انرژی می کند مواد غذایی گفته می شود. ', 'غذا تامین کننده ماده وانرژی در بدن موجود زنده به شمار میرود هر چیزی  که این دو نیاز را در بدن موجود زنده تامین کند غذا به شمار میرود', 19, NULL, '{"{\"answer\": \"مواد عضوی\", \"isCorrect\": false}","{\"answer\": \"مواد غیر عضوی\", \"isCorrect\": false}","{\"answer\": \"همه درست است\", \"isCorrect\": false}","{\"answer\": \"مواد غذایی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'a14726d0-168b-4c4d-a3a3-ae880c4c2432', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('سکروز از جمله کدام قند ها می باشد؟', 'اصطلاح (Disacharid) به قند های دو قیمته گفته میشود مثال آن :سکروز است.سکروز از یک واحد گلوکوز و یک واحد فروکتوز ساخته شده است.', 'قند های دو قیمته یا دای سکراید از طریق یکجا شدن دو مونوسکراید تحت پارچه شدن آب به وجود می آید. ', 20, NULL, '{"{\"answer\": \"قند های یک قمیته\", \"isCorrect\": false}","{\"answer\": \"قند های چند قمیته\", \"isCorrect\": false}","{\"answer\": \"هیج کدام \", \"isCorrect\": false}","{\"answer\": \"قند های دو قیمته\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '5403a7a6-a241-483d-bb0d-042d937c2bc8', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('عمده ترین مواد غذایی از لحاظ تولید انرژی که در عملیه میتابولیزم ارزش دارند به دسته های ذیل تقسیم شده است ؟', 'عمده ترین مواد غذایی که در متابولیزم (سوخت و ساز)از لحاظ تولید انرژی ارزش دارند به سه دسته قند ها ، پروتین ها ،شحمیات  تقسیم می شوند.', 'قندها مهمترین تامین کننده های انرژی حجرات محسوب میشوند ولی شحمیات انرژی را به مقدار زیاد در خود ذخیره میکند پروتین ها اخرین منبع انرژی حجروی محسوب میشود که در نبود قند ها و شحمیات مورد استفاده قرار میگیرند ', 19, NULL, '{"{\"answer\": \"چهار دسته\", \"isCorrect\": false}","{\"answer\": \"دودسته \", \"isCorrect\": false}","{\"answer\": \"پنج دسته\", \"isCorrect\": false}","{\"answer\": \"سه دسته\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'ce126369-220a-48d3-b045-525504694de9', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('قند ها ،پروتین و شحمیات در موجودیت اکسجن احتراق نموده و این عمل احتراق را به نام چه یاد می کند؟', 'قند ها ،پروتین ها و شحمیات در موجودیت اکسیجن احتراق نموده واین عمل اکسیدیشن نام دارد. ', 'اکسیدیشن سبب تجزیه و اکسیداسیون مواد عضوی و تبدیل آن به مالیکول های کوچک تر و سرانجام آن مواد فاضله و انرژی مؤلده می شود.', 19, NULL, '{"{\"answer\": \"ایملیشن\", \"isCorrect\": false}","{\"answer\": \"دیسملیشن\", \"isCorrect\": false}","{\"answer\": \"فتوسنتز\", \"isCorrect\": false}","{\"answer\": \"اکسیدیشن\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '13604814-4906-46fa-9448-460435a57bff', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('برای پی بردن به درست یا نادرست بودن فرضیه باید ..... صورت بیگیرد؟', 'فرضیه فقط یک احتمال است وزمانی پذیرفته می شود که بوسیله ازمایش تحلیل شود ودرست وغلط بودن ان به اثبات برسد ', 'تحلیل فرضیه به قدری مهم است که یک فرضیه قابل ازمایش وتحلیل نباشد  اهمیت علمی ان از بین میرود ', 5, NULL, '{"{\"answer\": \" تحلیل فرضیه\", \"isCorrect\": false}","{\"answer\": \"آزمایش\", \"isCorrect\": false}","{\"answer\": \"مشاهده\", \"isCorrect\": false}","{\"answer\": \"تحلیل فرضیه،ازمایش\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '3412f707-9ebb-4b53-b0c6-d6c007c9433e', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('Mosquitoes مربوط کدام صنف ارتورپود است ؟', 'mosquitoes به معنای پشه است ودر صنف حشرات Insects قرار دارد ', 'پشه بدن نرم ونازک داشته وخرطوم سوراخ کننده دارد و اغلب آنها  سبب انتقال امراض میشود ', 87, NULL, '{"{\"answer\": \"Crustaecean\", \"isCorrect\": false}","{\"answer\": \"Diplodia\", \"isCorrect\": false}","{\"answer\": \"Arahnida\", \"isCorrect\": false}","{\"answer\": \"Insects\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '58fbe4c6-60f5-49aa-9001-8cc5e3c7190d', 'cba94f01-9816-47bb-a8ad-9100133ab6f6', 'e5a85c30-20cc-4b26-a305-ea62eea17489'),
	('یکی از گزینه های ذیل از مهمترین تامین کنند های انرژی می باشد؟', 'مهم ترین تامین کننده انرژی در بدن قند ها  می باشند.', 'شحمیات انرژی ذخیره شده بیشتری نسبت به قند ها دارند ولی در هنگام اکسیدایشن موادی تولید میکند که باعث مسمومیت میشود به همین دلیل منبع دوم انرژی محسوب میشود اما قند ها به اسانی می سوزند  ', 20, NULL, '{"{\"answer\": \"پروتین\", \"isCorrect\": false}","{\"answer\": \"شحمیات\", \"isCorrect\": false}","{\"answer\": \"منرالها\", \"isCorrect\": false}","{\"answer\": \"قند ها\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'eaa836f1-3dc1-458b-b41e-d2e22fa0a7f8', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('انرژی که از سوخت یک گرام ماده قندی حاصل می شود بالغ به چند کیلو کالوری است؟', 'انرژی که از سوخت یک گرام ماده حاصل می شود بالغ بر 4 کیلو کالوری 4KCal است. ', 'کالوری عبارت است آن مقدار حرارت است که یک ملی لیتر آب خاالص را یک درجه سانتی گراد ارتقا دهد.', 20, NULL, '{"{\"answer\": \"3KCal\", \"isCorrect\": false}","{\"answer\": \"2KCal\", \"isCorrect\": false}","{\"answer\": \"1KCal\", \"isCorrect\": false}","{\"answer\": \"4KCal\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '621c0cd8-b408-4694-980b-07035bcac406', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('مار ها به صورت عموم در تیر کمر خود چند حلقه دارد ؟', 'مار ها بدن طویل وباریک دارند در بعضی از آنها تیر کمر از 200تا400حلقه دارد وبدون پای است ', NULL, 119, NULL, '{"{\"answer\": \"100 تا 200 \", \"isCorrect\": false}","{\"answer\": \"100 تا 300 \", \"isCorrect\": false}","{\"answer\": \"200 تا 500 \", \"isCorrect\": false}","{\"answer\": \"200 تا 400 \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '6ea7befc-0d67-42b4-908f-b7763602c03c', 'cba94f01-9816-47bb-a8ad-9100133ab6f6', 'e5a85c30-20cc-4b26-a305-ea62eea17489'),
	('مواد قندی در ترکیب خود  کدام یک ازعناصر ذیل را دارد؟', 'مواد قندی مرکباتی هستند که در ترکیب خود کاربن ، هایدروجن ،اکسیجن دارند. ', 'زنجیره کربن وهایدروجن ساختار اصلی قندها را تشکیل می دهد وبه همین دلیل به نام کاربوهایدریت  شناخته میشود ودر ان  اتم های اکسیجن با تعداد مشخص وجود دارد ', 20, NULL, '{"{\"answer\": \"کاربن\", \"isCorrect\": false}","{\"answer\": \"هایدروجن\", \"isCorrect\": false}","{\"answer\": \"اکسجن\", \"isCorrect\": false}","{\"answer\": \"کاربن،هایدروجن،اکسیجن\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '456936ca-9dc2-4aa9-9db1-70e3e8966c27', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('فرمول جمعی قند ها عبارت از؟', 'فرمول جمعی قند ها Cx(H2O)y می باشد.', 'در قند ها کربن  اکسیجن از نظر تعداد باهم برابر است وهایدروجن دوبرابر کربن است ', 20, NULL, '{"{\"answer\": \"Cₓ(H₃O)\", \"isCorrect\": false}","{\"answer\": \"Cₓ(H₄O)ᵧ\", \"isCorrect\": false}","{\"answer\": \"Cₓ(HO₂)ᵧ\", \"isCorrect\": false}","{\"answer\": \"Cₓ(H₂O)ᵧ\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '68e076d8-6e7d-4b9b-aee7-a983d37628d3', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
	('کدام یکی از قند های ذیل از جمله قند های یک قمیته است؟', 'اصطلاح(Monosacharid) به قند های یک قیمته گفته میشود مثال های آن : گلوکوز ،مالتوز ،فروکتوز است.', 'قند های یک قیمته واحدهای ساختمانی دیگر مواد قندی هستند.همه ی قند های یک قیمته شیرین هستند ', 20, NULL, '{"{\"answer\": \"گلوکوز\", \"isCorrect\": false}","{\"answer\": \"مالتوز\", \"isCorrect\": false}","{\"answer\": \"فروکتوز\", \"isCorrect\": false}","{\"answer\": \"گلوکوز ،مالتوز،فروکتوز\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '859828d0-dad9-48c4-9b2c-75b8d0b1032d', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'f23aca64-2814-4041-a021-dc6e81f67d24'),
