', NULL, 31, NULL, '{"{\"answer\": \"در اطراف \", \"isCorrect\": false}","{\"answer\": \"بیرون ساختمان \", \"isCorrect\": false}","{\"answer\": \"هیچکدام\", \"isCorrect\": false}","{\"answer\": \"قسمت مرکزی \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'bf898808-624c-4385-beaf-0eef741710fc', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'bc254243-7623-49a0-9d8d-c570e5b409b8'),
	('مرکب بیوتان دارای چند ایزومیر است؟
