	('یکی از این واژه ها به معنای (بهبود یافتن زخم) است؟', 'التیام(اسم مصدر):به هم پیوستن دو چیز،بهبود یافتن زخم.(فرهنگ معین)', NULL, 148, NULL, '{"{\"answer\": \"تورم\", \"isCorrect\": false}","{\"answer\": \"جراحت\", \"isCorrect\": false}","{\"answer\": \"انسداد\", \"isCorrect\": false}","{\"answer\": \"التیام\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'a2347801-f274-4249-a3e7-616a39d501aa', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('اثر مشهور(کلیسا نوتردام پاریس)نوشته یکی از اینهاست؟', 'گوژپشت نوتردام یا نوتردام دو پَقی (نتردامِ پاریس)  رمانی است نوشتهٔ ویکتور هوگو، نویسندهٔ نامدار فرانسوی، که در سال 1831 میلادی انتشار یافت. این کتاب یکی از آثار ادبی برجستهٔ جهان است که در سبک رمانتیک نگاشته شده‌است.', 'نام اصلی این رمان، «نوتردام دو پاری» به معنی نوتردام پاریس است و قهرمان راستین این رمان کلیسای نوتردام پاریس است. ', 122, NULL, '{"{\"answer\": \"همینگوی\", \"isCorrect\": false}","{\"answer\": \"دانته\", \"isCorrect\": false}","{\"answer\": \"آنتون چخوف\", \"isCorrect\": false}","{\"answer\": \"ویکتور هوگو\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '04ae5d67-735c-411a-9174-f07d4bcf5658', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('آثار معروف هوگو عبارتند از؟', NULL, NULL, 122, NULL, '{"{\"answer\": \"کلیسای نوتردام پاریس\", \"isCorrect\": false}","{\"answer\": \"کار گران دریا\", \"isCorrect\": false}","{\"answer\": \"مردی که میخندد\", \"isCorrect\": false}","{\"answer\": \"کلیسای نوتردام پاریس، کار گران دریا، مردی که میخندد\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'a73d6c7f-6d67-4c9f-9289-3b4d71631c8f', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('از آثار ویکتور هوگو می باشد ؟', 'ویکتور هوگو این رمان را در بروکسل نوشت و آن را در آوریل سال 1869.م منتشر کرد. داستان کتاب در اوائل قرن هژدهم در انگلستان روی می‌دهد.گفته شده شخصیت ابرشرور جوکر در سری کتاب های مصور بتمن، از روی همین اثر الهام‌گرفته شده است.', NULL, 122, NULL, '{"{\"answer\": \"کمیدی الهی\", \"isCorrect\": false}","{\"answer\": \"بهشت گمشده\", \"isCorrect\": false}","{\"answer\": \"درخت آسوریک\", \"isCorrect\": false}","{\"answer\": \"مردی که می خندد\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '9b76f014-415b-48d2-a40b-2d2e94224aed', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('کتاب معروف (بینوایان ) اثری یکی از اینها است ؟', 'یکی از برزگترین رمان های قرن 19 میلادی است با شروع رسیدن آن در 1832 میلادی در پاریس، این رمان از زندگی چند شخصیت و تمرکز بر مبارزات محکوم سابقه داری به نام ژان والژان و به رستگاری رسیدن او شکل گرفت .', NULL, 122, NULL, '{"{\"answer\": \"همینگوی\", \"isCorrect\": false}","{\"answer\": \"میلتون\", \"isCorrect\": false}","{\"answer\": \"دانته\", \"isCorrect\": false}","{\"answer\": \"ویکتور هوگو\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '40b26f99-ad58-439c-9882-50dc4bcadd0a', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('قدمت نقاشی چند برابر زبان نوشتاری است ؟', 'نقاشی، نگارگری یا رسم، فرایندی است که طی آن رنگ، بر روی یک سطح مسطح مانند کاغذ یا بوم ایجاد نقش می‌کند و اثری خلق می‌شود.قدیمی‌ترین نقاشی‌ در جهان متعلق به حدود 32000 هزار سال پیش در گروته شاوه فرانسه قرار دارد.', 'بسیاری از آثار شناخته شده و مشهور هنری امروزی، مانند مونالیزا، شب پرستاره، دختری با گوشواره مروارید و تولد ونوس نقاشی‌های برجسته‌ای هستند که در سراسر جهان از آن‌ها الگو برداری شده است. ', 128, NULL, '{"{\"answer\": \"10 برابر\", \"isCorrect\": false}","{\"answer\": \"4 برابر\", \"isCorrect\": false}","{\"answer\": \"2 برابر\", \"isCorrect\": false}","{\"answer\": \"6 برابر\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'bfb7b395-46e3-4ec9-a4e0-8d6e36bee172', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('معنای دقیق واژه (دیبا) یکی از گزینه های زیر است؟', NULL, NULL, 150, NULL, '{"{\"answer\": \"قالین\", \"isCorrect\": false}","{\"answer\": \"گل لاله\", \"isCorrect\": false}","{\"answer\": \"کتان\", \"isCorrect\": false}","{\"answer\": \"پارچه ابریشمی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '90c9c00c-6649-412e-b7fc-4c5d69afc464', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
	('از رباعی سرایان دوره سامانی است؟', 'برخی رودکی را واضع این نوع شعر (رباعی) می‌دانند و گویند که وزن آن را از ترانه‌ای که کودکی که به هنگام گردو بازی می‌خوانده ((غلتان غلتان همی‌رود تا بن گو)) اقتباس کرده‌است.', NULL, 135, NULL, '{"{\"answer\": \"بیدل\", \"isCorrect\": false}","{\"answer\": \"سعدی\", \"isCorrect\": false}","{\"answer\": \"صایب\", \"isCorrect\": false}","{\"answer\": \"رودکی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'dc70d46f-3ef3-42fd-8542-74b739685d02', '091aeffc-30d1-40d5-98b0-cc77a695b840', '160a155e-26d3-4b1e-87e5-45061140b905'),
