	('مقدار فیصدی کاربن در ذغال سنگ معمولی چند می باشد ؟', 'مقــدار فيصــدى کاربن در ذغال سنگ معمولی در حدود %80 می باشــد.', NULL, 49, NULL, '{"{\"answer\": \"85%\", \"isCorrect\": false}","{\"answer\": \"70%\", \"isCorrect\": false}","{\"answer\": \"75%\", \"isCorrect\": false}","{\"answer\": \"80%\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '8f372fce-b6ad-42f0-a09d-617f03645ecd', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('برایی تشخیص اثر خط یک منرال چگونه عمل می کنیم ؟', ' اثر خط کش کردن يک پارچه منرال بالاى يک تخته کاشى سفيد است', NULL, 8, NULL, '{"{\"answer\": \"پارچه منرال را بالای یک تخته آهنی کش می کنم\", \"isCorrect\": false}","{\"answer\": \"پارچه منرال را بالای یک تخته سنگ سیاه کش می کنیم\", \"isCorrect\": false}","{\"answer\": \"تباشیر را بالای آن کش می کنیم\", \"isCorrect\": false}","{\"answer\": \"پارچه منرال را بالای یک تخته کاشی سفید کش می کنیم \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '4f9ced03-fb85-4508-b67b-a8991cab0e95', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('کدام نوع ذغال سنگ حرارت کم تولید میکند ؟', 'لگنایت که فیصدی کاربن آن  %70 است نسبت به آنتراسیت، کوکس و ذغال معمولی دارای کاربن کمتر است بنابراین حرارت کمتری تولید می کند', NULL, 49, NULL, '{"{\"answer\": \"انتراسیت \", \"isCorrect\": false}","{\"answer\": \"کوکس\", \"isCorrect\": false}","{\"answer\": \"ذغال سنگ معمولی\", \"isCorrect\": false}","{\"answer\": \"لگنایت \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'ade8fb6c-9e29-4f4c-8a86-1182e95ecec7', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('زغال انتراسیت از جمله کدام سنگها محسوب می شود ؟', ' ذغال سنگ نوعى ســنگ رسوبى است که از بقاياى نباتات روى زمين بهوجود می آيد و آنتراسبت نوع ذغال سنگ رسیده  که از دگرگونی ذغال معمولی حاصبل می شود', 'به دلیل اینکه آنتراسیت تحت فشار و گرما قرار می گیرد متحوله می شود بنابراین در دسته سنگ های متحوله قرار می گیرد', 49, NULL, '{"{\"answer\": \"رسوبی\", \"isCorrect\": false}","{\"answer\": \"گرانو دیوریت ها \", \"isCorrect\": false}","{\"answer\": \"باتولیتها \", \"isCorrect\": false}","{\"answer\": \"متحوله \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '4fb8eb58-a791-4a4a-b783-7108d698ef99', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('گرانیتها از جمله کدام سنگهای عمقیه محسوب می شود ؟', 'گرانیتها از جمله  سنگهای عمقیه مگماتیکی محسوب می شود', 'اصطلاح عمقیه فقط برای سنگ های مگماتیکی استفاده می شود', 49, NULL, '{"{\"answer\": \"متحوله و مگماتیکی\", \"isCorrect\": false}","{\"answer\": \"رسوبی\", \"isCorrect\": false}","{\"answer\": \"متحوله \", \"isCorrect\": false}","{\"answer\": \"مگماتیکی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'd5fc0ba0-f509-44ee-bbc9-0430157951e9', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('سنگ های کابوناتی در حدود چند فصید در سنگ های رسوبی موجود می باشد ؟', 'ســنگها ی کاربوناتی که قســمت عمدة آن را کلســيم کاربونيت(CaCO₃) تشــکيل می دهد و در حدود 22% در ســنگهاى رسوبى موجود می باشد', NULL, 56, NULL, '{"{\"answer\": \"25%\", \"isCorrect\": false}","{\"answer\": \"15%\", \"isCorrect\": false}","{\"answer\": \"30%\", \"isCorrect\": false}","{\"answer\": \"22%\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'd924898b-757f-49b1-ba7b-f3d3ed02104e', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('احجار کوهی در اعماق زمین تحت کدام عوامل به طبقات بالای قرار گرفته و متراکم می شود ؟', 'احجار کوهی  در اعماق زميــن تحت فشــار طبقات بالايى قرار گرفته و متراکم می شــوند', 'وزن سنگ هایی بالایی فشار بالایی را روی سنگ های زیرین ایجاد میکند که باعث سنگ شدن رسوبات می شود و سنگ رسوبی را ایجاد می کند هرگاه این فشار زیاد گردد باعث می شود سنگ رسوبی یا ناریه دوباره منرال های آن متبلور شود و تبدیل به سنگ متحوله شود. فشار می تواند تعیین کند کدام شکل منرال پایدار است. برخی از منرال ها  ممکن است به دلیل افزایش فشار ، به منرال هایی با ترکیب مشابه تبدیل شوند اما آرایش اتمی متفاوتی داشته باشند', 52, NULL, '{"{\"answer\": \"حرارت \", \"isCorrect\": false}","{\"answer\": \"غلظت محلول های کیمیاوی \", \"isCorrect\": false}","{\"answer\": \"تحول و تداوم\", \"isCorrect\": false}","{\"answer\": \"فشار \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '9a1ca449-8f65-4658-9708-dd45ff6c9549', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('برای ساختن ظروف سفالی کدام منرال را همرای آب یکجا نموده و ماده خمیر مانند را بدست می آورند ؟', 'گل رس را که از جمله منرال است براى ساختن ظروف سفالى همراى آب يکجا نموده و ماده خمير مانند را به دســت می آورند', 'گل رس : خاصیت خمیری از خود نشان می‌دهند. خمیری بودن، خاصیت بتونه شکلی است ', 52, NULL, '{"{\"answer\": \"سنگ ریگی \", \"isCorrect\": false}","{\"answer\": \"گل تنور\", \"isCorrect\": false}","{\"answer\": \"همه درست است\", \"isCorrect\": false}","{\"answer\": \"گل رس\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'd7677b5c-9ddc-4796-918a-74f28e290032', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('پروسه را که در نتیجه آن سنگ های میتامور فیکی تشکیل می شوند عبارت اند از ؟', 'پروســة را که در نتيجة آن سنگهاى ميتامورفيکى تشکيل می شوند، به نام ميتامورفيزم ياد مینمايند که به معناى تغيير و تحول می باشد', NULL, 52, NULL, '{"{\"answer\": \"میتا اتموسفیر \", \"isCorrect\": false}","{\"answer\": \"میتامگماتیکی \", \"isCorrect\": false}","{\"answer\": \"همه غلط است \", \"isCorrect\": false}","{\"answer\": \"میتامور فیزم \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '2a60bb6d-5a4c-44c5-8528-d18540e856de', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('در اثر کدام عامل سنگ های قبلا تشکیل شده (مگماتیکی و رسوبی ) از حالت اولی خود تغییر نموده شکل و ترکیب جدیدی را اختیار می نمایند ؟', 'در تشــکيل سنگهاى ميتامورفيکى عامل فشار و حرارت رول اساســى ايفا می کند براثر فشــار و حرارت با موجوديت محلولهاى کيمياوى سنگ ً هاى قبلا تشــکيل شده (مگماتيکى و رسوبى) از حالت اولى خود تغيير نموده شکل وترکيب جديدى را اختيار می نمايند', 'منرالها در شرایط خاصی از فشار و دما پایدار هستند. هنگامی که فشار و  دما تغییر می کند ، واکنشهای شیمیایی باعث می شوند که مواد معدنی موجود در سنگ به مجموعه ای تبدیل شوند که در فشار و دمای جدید پایدار باشد.', 52, NULL, '{"{\"answer\": \"ترسبات\", \"isCorrect\": false}","{\"answer\": \"حرکت امواج بحری\", \"isCorrect\": false}","{\"answer\": \"فرسایش\", \"isCorrect\": false}","{\"answer\": \"فشار ، حرارت و موجودیت محلول های کیمیاوی  \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '3da42fc3-b502-4c87-9e55-7a2878d0f719', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
	('در تشکیل سنگ های میتامورفیکی کدام عامل رول اساسی را ایفا می کند ؟', 'در تشــکيل سنگهاى ميتامورفيکى عامل فشار و حرارت رول اساســى ايفا می کند', 'فشار و حرارات در محل تصادم دو پلیت  و افزایش عمق زیاد می شود و حرارت از دیواره های اتاق مگما به سنگ های اطراف منتقل می شود', 52, NULL, '{"{\"answer\": \"حرکت امواج بحری\", \"isCorrect\": false}","{\"answer\": \"ولکانو\", \"isCorrect\": false}","{\"answer\": \"آب و هوا\", \"isCorrect\": false}","{\"answer\": \"فشار  و حرارت \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '853d5c36-1501-425b-85c4-65c7773bd48d', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'c4c56fd5-8c4e-460a-b45c-84c30ba4111d'),
