	('سیلاب های کدام دریای ذیل تلفات زیاد مالی و جانی را به بار می آورد ؟', 'گنگا بزرگ ترین دریای شبه قاره هند می باشد و این دریا برای پیروان آیین هندو نوعی تقدس دارد . ', NULL, 151, NULL, '{"{\"answer\": \"تایمز\", \"isCorrect\": false}","{\"answer\": \"آمو\", \"isCorrect\": false}","{\"answer\": \"دجله\", \"isCorrect\": false}","{\"answer\": \"گنگا\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '3292941c-083a-4ad4-bf60-2bd4e15e4431', '091aeffc-30d1-40d5-98b0-cc77a695b840', '21717b1e-0026-4805-b9f6-4ebf08a1faf5'),
	('تخریب سیلاب درکدام یکی از جاهای ذیل زیاد می باشد؟', 'جریان آب در بستر خویش مقداری گل و لای با خود همراه دارد که به محض ورود به بحرها و ترسب، بصورت مثلثی در میاید که راس آن بطرف رودخانه میباشد. آنرا به یونانی دلتا ( مصب ) گویند .', NULL, 151, NULL, '{"{\"answer\": \"در جائیکه استحکام ضعیف است\", \"isCorrect\": false}","{\"answer\": \"در نقاط هموار \", \"isCorrect\": false}","{\"answer\": \"همه درست است\", \"isCorrect\": false}","{\"answer\": \"در مصب دریا\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '35aa36bc-aa28-4abd-9211-c1bbdc010b93', '091aeffc-30d1-40d5-98b0-cc77a695b840', '21717b1e-0026-4805-b9f6-4ebf08a1faf5'),
	('سیلاب های کوهستانی کدام یک از اینها هستند؟', ' در مناطق كوهستاني سيلاب هايي كه به صورت هاي متفاوت، با ذوب برف افزايش مي يابد؛ روي مي دهند و منطقه اي به نام سيلاب دشت را در اطراف دریا به وجود مي آورد.', 'تحقیقات اخیر نشان داد از سال 1990 تا 2015 در مجموع 401 دریاچه یخچالی  جدید شکل گرفته و وسعت منطقه دریاچه های یخچالی در این مدت 14.1فیصد بیشتر شده که این مسئله احتمال روان شدن سیلاب دریاچه های یخچالی را که جان مردم مناطق پایین دستی نپال و منطقه خودمختار تبت چین را تهدید می کند، افزایش داده است. ', 152, NULL, '{"{\"answer\": \"سیلاب دریایی\", \"isCorrect\": false}","{\"answer\": \"سیلاب سونامی\", \"isCorrect\": false}","{\"answer\": \"هیچ کدام \", \"isCorrect\": false}","{\"answer\": \"سیلاب یخچالی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '3efe5f10-3d53-474c-8387-93f32c64e67f', '091aeffc-30d1-40d5-98b0-cc77a695b840', '21717b1e-0026-4805-b9f6-4ebf08a1faf5'),
	('یکی از ارگان های ذیل در کاهش خطر سیلاب مسؤلیت دارد؟', ' رسانه ها قدرت دارند تا در معرفی بحران و حوادث و رخدادهای تاسف بار، به وظایفی از قبیل تشکیل کمیته هایی به عنوان یکی از بازوهای اصلی ستاد مدیریت، اطلاع رسانی به موقع، صحیح و صادقانه، ایجاد ارتباط مستقیم با مردم و برقراری جو روانی نشاط آور برای تداوم زندگی بین مردم بپردازند. ', NULL, 154, NULL, '{"{\"answer\": \"منابع ملی\", \"isCorrect\": false}","{\"answer\": \"منابع بین الملل\", \"isCorrect\": false}","{\"answer\": \"ادارات  \", \"isCorrect\": false}","{\"answer\": \"رسانه های جمعی \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '7a81da20-2087-4aa9-ac1b-8bf89ddd3b23', '091aeffc-30d1-40d5-98b0-cc77a695b840', '21717b1e-0026-4805-b9f6-4ebf08a1faf5'),
