	('میخانیک کوانتوم به چه نام یاد می شود ؟', 'اساس نظریات فزیک مدرن را دو نظریه نسبیت و کوانتوم تشکیل می دهند.', 'میخانیک کوانتوم شاخه ای از فزیک نظری است که با پدیده های فزیکی در مقیاس میکروسکوپی سر و کار دارد.تفاوت اساسی میخانیک کوانتومی با میخانیک کلاسیک در این است که میخانیک کوانتومی توصیفی سازگار با تجربه و آزمایش ها از ذرات در اندازه های اتمی و زیر اتمی  را نشان می دهد در حالی که میخانیک کلاسیک در محدوده میکروسکوپی نتایج نادرستی را نشان می دهد.', 106, NULL, '{"{\"answer\": \"فزیک کلاسیک\", \"isCorrect\": false}","{\"answer\": \"فزیک الکترودینامیک\", \"isCorrect\": false}","{\"answer\": \"هیچکدام\", \"isCorrect\": false}","{\"answer\": \"فزیک معاصر\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '07d132e3-2494-4321-ad2e-2b137dc5d1bc', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('در حادثه فوتوالکتریک با کم شدن فریکونسی نور مونوکروماتیک ولتاژ متوقف کننده چگونه تغییر می کند ؟', 'ولتاژ متوقف کننده به فریکونسی نور ورودی و جنس الکترودی که نور بر آن وارد می شود بستگی دارد.', NULL, 119, NULL, '{"{\"answer\": \"زیاد می شود\", \"isCorrect\": false}","{\"answer\": \"هم کم و هم زیاد می شود\", \"isCorrect\": false}","{\"answer\": \"ثابت می ماند\", \"isCorrect\": false}","{\"answer\": \"کم می شود\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'e2502d20-9471-4386-b2f5-a4c38107d699', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('واحد اندازه گیری فریکونسی چیست ؟', 'امروزه به افتخار فزیک دان آلمانی قرن نوزدهم، هاینریش رودولف هرتز، فریکونسی بر مبنای هرتس بیان می‌شود. در اصل یک هرتس برابر با یک نوسان در ثانیه است. همچنین یک کیلو هرتس برابر با ۱۰۰۰ هرتس و یک مگا هرتس برابر با ۱۰۰۰۰۰۰ میلیون هرتس است.', NULL, 7, NULL, '{"{\"answer\": \"sec\", \"isCorrect\": false}","{\"answer\": \"rad/sec\", \"isCorrect\": false}","{\"answer\": \"rad\", \"isCorrect\": false}","{\"answer\": \"Hz\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'e2ec9a18-85bf-4430-92e8-6bf9ae529b2a', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('اگر بالای یک جسم انرژی وارده 550j و ضریب جذب 0.7 باشد ، چقدر انرژی توسط جسم جذب شده است؟', NULL, NULL, 109, NULL, '{"{\"answer\": \"450J\", \"isCorrect\": false}","{\"answer\": \"300J\", \"isCorrect\": false}","{\"answer\": \"285J\", \"isCorrect\": false}","{\"answer\": \"385J\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '1af71f5d-9aca-4a6d-b514-b2bfb4d14720', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('کدام بخش ذیل فزیک از سرعت های خیلی بزرگ بحث می کند ؟', 'اساس فزیک مدرن را دو نظریه تشکیل می دهد.نظریه نسبیت و نظریه کوانتوم. نظریه نسبیت در مورد اجسامی صحبت می کند که سرعتی نزدیک به سرعت نور دارند.', NULL, 106, NULL, '{"{\"answer\": \"میخانیک\", \"isCorrect\": false}","{\"answer\": \"ترمودینامیک\", \"isCorrect\": false}","{\"answer\": \"میخانیک کوانتوم\", \"isCorrect\": false}","{\"answer\": \"نسبیت\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '1cd0ac7c-849d-426a-9161-835280449290', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('نظر به فرمول انیشتین کدام کتله، انرژی 9.10¹³ ژول را تولید می کند.در صورتی که سرعت نور 3.10⁸ متر بر ثانیه باشد.', NULL, NULL, 128, NULL, '{"{\"answer\": \"100gr\", \"isCorrect\": false}","{\"answer\": \"1kg\", \"isCorrect\": false}","{\"answer\": \"10gr\", \"isCorrect\": false}","{\"answer\": \"1gr\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '6401a68e-d4c6-4192-bf59-a5c4bcce5b2b', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('در پدیده ی فوتوالکتریک ولتاژ متوقف کننده به کدام عامل بستگی ندارد ؟', NULL, NULL, 119, NULL, '{"{\"answer\": \"فریکونسی نور وارده\", \"isCorrect\": false}","{\"answer\": \"طول موج نور وارده\", \"isCorrect\": false}","{\"answer\": \"جنس الکترود فلزی که نور بر آن وارد می شود\", \"isCorrect\": false}","{\"answer\": \"شدت شعاع وارده\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'e9e725b6-2087-42f2-bf86-7bc316375b1c', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('نظریه نسبیت برای اولین بار توسط چه کسی مطرح شد ؟', NULL, NULL, 106, NULL, '{"{\"answer\": \"ماکس پلانگ\", \"isCorrect\": false}","{\"answer\": \"بورن\", \"isCorrect\": false}","{\"answer\": \"نیوتن\", \"isCorrect\": false}","{\"answer\": \"انیشتین\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '0558a342-eed0-4290-9db0-7e2ba37ab8b2', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('در کدام طول موج ها فزیک کلاسیک با تجربه سازگاری دارد ؟', 'در طول موج های بلند، نظریه کلاسیک با تجربه سازگاری دارد. اما در طول موج های کوتاه فزیک کلاسیک پیش بینی می کند که مقدار انرژی تابشی پخش شده باید لایتناهی باشد اما تجربه نشان می دهد که مقدار این انرژی بسیار کم است.', NULL, 108, NULL, '{"{\"answer\": \"طول موج های کوتاه\", \"isCorrect\": false}","{\"answer\": \"در هیچ طول موجی سازگاری ندارند.\", \"isCorrect\": false}","{\"answer\": \"فزیک کلاسیک با نتایج حاصل از تجربه در همه طول موج ها سازگاری دارد.\", \"isCorrect\": false}","{\"answer\": \"طول موج های بلند\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '1881849a-df40-431d-8ced-b7ebd6aad6de', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('ضریب جذب چه مقایری را می تواند داشته باشد ؟', 'ضریب جذب برابر است با نسبت مقدار انرژی جذب شده به کل انرژی وارده بر جسم. بنابراین مقدار عددی صورت هیچ گاه از مخرج بزرگتر نمی شود.بنابراین ضریب جذب کمتر از یک است و چون جسم سیاه تمام انرژی وارده را جذب می کند پس ضریب جذب آن برابر یک هست. نتیجه ای که میگیریم این است که ضریب جذب کوچکتر یا مساوی با یک هست همیشه', NULL, 109, NULL, '{"{\"answer\": \"بزرگتر از یک\", \"isCorrect\": false}","{\"answer\": \"همیشه برابر با یک\", \"isCorrect\": false}","{\"answer\": \"کوچکتر مساوی 10\", \"isCorrect\": false}","{\"answer\": \"کوچکتر مساوی یک\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '6e88b39d-6c89-4bbc-95c0-b530eea6f0f3', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('نصف عمر 4kg کتله رادیواکتیف 60sec است، بعد از 2min چقدر کتله نامتلاشی باقی میماند ؟', NULL, NULL, 156, NULL, '{"{\"answer\": \"4kg\", \"isCorrect\": false}","{\"answer\": \"2kg\", \"isCorrect\": false}","{\"answer\": \"3kg\", \"isCorrect\": false}","{\"answer\": \"1kg\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '8206722e-6be2-4c44-b616-fe4887276a2e', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('تعریف الکترون ولت چیست ؟', 'الکترون ولت : واحد اندازه گیری انرژی است که که با نماد e.v نمایش داده می شود.و اندازه آن برابر است با انرژی یک الکترون تحت ولتاژ یک ولت', NULL, 117, NULL, '{"{\"answer\": \"مقدار انرژی چارج برقی برابر به یک کولمب تحت ولتاژ یک ولت\", \"isCorrect\": false}","{\"answer\": \"به الکترون های جدا شده از سطح فلز در پدیده فوتوالکتریک گفته می شود\", \"isCorrect\": false}","{\"answer\": \"هیچکدام\", \"isCorrect\": false}","{\"answer\": \"تغییر مقدار انرژی یک الکترون تحت ولتاژ یک ولت\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '99d8a667-c3b1-44d6-bca6-906f8392e3fc', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('توان تابشی هر جسم با ضریب جذب آن جسم چه ارتباطی دارد ؟', 'شدت تابشی یا توان تابشی یک جسم برابر است با مقدار کل انرژی تابش های الکترومقناطیسی که در انتروال زمانی یک ثانیه از واحد سطح یک جسم پخش می شود..پس هر چه ضریب جذب یک جسم بیشتر باشد شدت تابشی آن نیز بزرگ تر است.پس توان تابشی با ضریب جذب نسبت مستقیم دارد.', 'جسم سیاه بهترین پخش کننده و هم بهترین جذب کننده امواج الکترومقناطیسی است. درواقع می توان گفت هر جسمی که جذب کننده ایده ال باشد از آن طرف پخش کننده خوبی هم هست پس ضریب جذب با توان تابشی نسبت مستقیم دارد.', 110, NULL, '{"{\"answer\": \"نسبت معکوس\", \"isCorrect\": false}","{\"answer\": \"توان تابشی دو چند ضریب جذب می باشد\", \"isCorrect\": false}","{\"answer\": \"توان تابشی با جذر ضریب جذب متناسب است\", \"isCorrect\": false}","{\"answer\": \"نسبت مستقیم\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '8327c743-018c-4393-bcc0-a4b3190606c9', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('اگر یک جسم میان خالی سیاه رنگ را در اختیار داشته باشیم کدام قسمت جسم را میتوان جسم سیاه در نظر گرفت ؟', NULL, NULL, 110, NULL, '{"{\"answer\": \"سطح بیرونی جسم \", \"isCorrect\": false}","{\"answer\": \"سطح داخلی جسم\", \"isCorrect\": false}","{\"answer\": \"تمام جسم \", \"isCorrect\": false}","{\"answer\": \"سوراخ جسم\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'b3d5ba37-12fd-45fb-9fbe-33ebfd63ec70', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
	('طیف نور پخش شده از بخار هر عنصر را چه می نامند ؟', 'طیف نور پخش شده از بخار رقیق هر عنصر را در حالتی که تحت ولتاژ بالا قرار می گیرد و آن طیف را تابش می کند طیف اتومی می نامند. که این طیف یک طیف ناپیوسته است.و از چند خط رنگی جدا از هم تشکیل شده است.', NULL, 113, NULL, '{"{\"answer\": \"طیف جذبی\", \"isCorrect\": false}","{\"answer\": \"طیف جذبی و اتومی\", \"isCorrect\": false}","{\"answer\": \"طیف جذبی و نشری\", \"isCorrect\": false}","{\"answer\": \"طیف اتومی یا نشری\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '9e3c0d07-1a81-4f96-9690-b171cf75d0c2', '0b1d65e2-07dd-44a1-adaf-a692788661c2', 'b5a615a7-1f2f-4c79-ba38-9e1b17526c2b'),
