	('درین آیت کریمه ( و اذ قال لقمن لابنه و هو یعظه یبنی لا تشرک بالله ان الشرک الظلم عظیم ) معنای درست از کلمه ( یعظه ) چیست ؟', NULL, 'ترجمه: و وقتی که لقمان در مقام پند و موعظه به فرزندش گفت: ای پسرم هرگز شرک به خدا نیاور که شرک بسیار ظلم بزرگی است.', 61, NULL, '{"{\"answer\": \"نیکی \", \"isCorrect\": false}","{\"answer\": \"دعوت \", \"isCorrect\": false}","{\"answer\": \"بدی \", \"isCorrect\": false}","{\"answer\": \"پند \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '9712352b-fc2b-46f5-9a50-ded73cb22eff', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای کلمه ( وهناً علی وَهنٍ ) چیست ؟', NULL, 'نظر به آیه ۱۴ سوره لقمان آمده که (وَهنًا عَلَی وَهن) به معنی ضعیفی بر ضعیفی آمده است.', 61, NULL, '{"{\"answer\": \"قوی بر قوی \", \"isCorrect\": false}","{\"answer\": \"ضعیفی بر قوی \", \"isCorrect\": false}","{\"answer\": \"قوی بر ضعیفی\", \"isCorrect\": false}","{\"answer\": \"ضعیفی بر ضعیفی\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '10021f3a-a92a-4726-8142-355fb014ae03', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('نخستین کسی که لقمان اندرزها و نصایح خود را متوجه او ساخت کی بود ؟', 'در قران در سوره لقمان بارها لقمان فرزندش را مورد خطاب قرار داده است.', 'لقمان با استفاده از علم و حکمت دیگران را به سوی خدا دعوت می نمود و به آنها پند و نصیحت می کردو نخستین کسی که لقمان اندرزها و نصایح خود را متوجه او ساخت پسرش بود', 62, NULL, '{"{\"answer\": \"کافران را \", \"isCorrect\": false}","{\"answer\": \"مشرکان \", \"isCorrect\": false}","{\"answer\": \"منافقان \", \"isCorrect\": false}","{\"answer\": \"پسرش\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '537ba9d2-ddad-421c-b8fd-ca6da449e1ff', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('بدترین انواع ظلم چیست ؟', NULL, 'لقمان حکیم فرزند خود را به توحید و یکتا پرستی دستور داده او را از شرک و عبادت غیر خدا بر حذر می سازد و استدلال می کند که شرک ظلم و گناه نا بخشودنی است.', 62, NULL, '{"{\"answer\": \"قتل \", \"isCorrect\": false}","{\"answer\": \"دروغ \", \"isCorrect\": false}","{\"answer\": \"زنا \", \"isCorrect\": false}","{\"answer\": \"شرک \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '2bf90c8e-caa4-4ca9-ac80-60879bfbc9c4', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('طاعت و فرمان برداری والدین چه وقت ساقط می شود ؟', NULL, 'هرگاه پدر و مادر به معصیت و نا فرمانی خدا امر نمایند طاعت و فرمان برداری شان ساقط می گردد.', 63, NULL, '{"{\"answer\": \"در زمانیکه والدین کافر باشد \", \"isCorrect\": false}","{\"answer\": \"در هنگام مرگ شان \", \"isCorrect\": false}","{\"answer\": \"در وقت که والدین مهربانی نداشته باشد \", \"isCorrect\": false}","{\"answer\": \"زمانیکه والدین به معصیت و شرک به خدا امر کند \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'b3bcc9f0-f7ea-4199-9ade-35f7e63a71ad', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('همراهی و همنشینی با والدین و برخورد نیک با ایشان در دنیا یکی گزینه های ذیل درست است ؟', NULL, 'همراهی و همنشینی با والدین و برخورد نیک با ایشان در دنیا واجب است حتی اگر کافر هم بوده باشند.', 65, NULL, '{"{\"answer\": \"فرض است \", \"isCorrect\": false}","{\"answer\": \"مستحب است \", \"isCorrect\": false}","{\"answer\": \"خوب است \", \"isCorrect\": false}","{\"answer\": \"واجب است \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '55cdb703-77da-4f5d-b70a-15a3de2922d3', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('درین آیت ( یَابُنَیَّ أَقِمِ الصَّلَاةَ وَ أمُر بِالمَعرُوفِ وَانهَ عَنِ المُنکَرِ وَاصبِر عَلی مَا أَصَابَکَ إِنَّ ذَلِکَ مِن عَزمِ الاُمُورِ "س: لقمان، آ:17 " ) کدام چیز ها را از عزم الامور ( امور سترگه و بر جسته ) خوانده شده است ؟', 'ترجمه: ای فرزندم نماز را بر پا دار و امر به معروف و نهی از منکر کن و بز آنچه به تو میرسد صبر نما که این نشانه یی از عزم ثابت در امور دنیا است.', 'ترجمه: ای فرزندم نماز را بر پا دار و امر به معروف و نهی از منکر کن و بر آنچه به تو میرسد صبر نما که این نشانه یی از عزم ثابت در امور دنیا است.', 66, NULL, '{"{\"answer\": \"بر پاداشتن نماز \", \"isCorrect\": false}","{\"answer\": \"امر به معروف و نهی از منکر \", \"isCorrect\": false}","{\"answer\": \"صبر و بر مصائب\", \"isCorrect\": false}","{\"answer\": \"برداشتن نماز، امر به معروف و نهی از منکر، صبر و بر مصائب\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '7f54fb43-4cc7-41e5-9da6-7267247aa778', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('جعلان در کجا زندگی می کند ؟', NULL, 'جعلان عبارت از جشره کوچکی است که در میان سرگین حیوانات زندگی میکند و غذای آن پارو و یا نجاست حیوانات است و هرگاه خوشبویی به او برسد میمیرد.', 72, NULL, '{"{\"answer\": \"پارو\", \"isCorrect\": false}","{\"answer\": \"نجاست \", \"isCorrect\": false}","{\"answer\": \"همه درست است \", \"isCorrect\": false}","{\"answer\": \"سرگین حیوانات \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'c8c0bf7c-6a38-446d-aa37-b167b8170725', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('این عبارت ( در راه رفتنت جانب اعتدال را بگیر ) معنی کدام یک از کلمات قرآنی است ؟', 'در آیه 19 سوره لقمان و اقصد فی مشیک به معنی در راه رفتنت جانب اعتدال را بگیر آمده است.', 'چنانچه در سوره لقمان وَاقصِد فِی مَشیِکَ به معنی در راه رفتنت جانب اعتدال را بگیر آمده است.', 66, NULL, '{"{\"answer\": \"و کذالک جعلنا کم امه وسطًا\", \"isCorrect\": false}","{\"answer\": \"واسع علیکم نعمه \", \"isCorrect\": false}","{\"answer\": \"مختال فخور \", \"isCorrect\": false}","{\"answer\": \"و اقصد فی مشیک \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '48b99bfb-11d6-4d79-ac89-14395a02e9c6', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای دقیق کلمه ( تپذیر ) چیست ؟', NULL, 'در سوره الاسراء بعد از رعایت حقوق خویشاوندان خداوند متعال از اسراف و تبذیر منع نموده است.', 90, NULL, '{"{\"answer\": \"صرفه جویی\", \"isCorrect\": false}","{\"answer\": \"سرپیچی \", \"isCorrect\": false}","{\"answer\": \"هیچکدام \", \"isCorrect\": false}","{\"answer\": \"اسراف\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '4cd651a8-18f9-4a3a-9086-d2654eb43297', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای این کلمه آیت ( وَاقصِد فِی مَشیِکَ ) چیست ؟', 'توصیه لقمان به فرزندش، براى رعایت اعتدال در رفتار و پرهیز از گفتار خشن، نمودى از حکمت وى است', 'راه رفتن خوب و مورد پسند خداوند همان راه رفتن متوازن و میانه است که از سستی ملال آور و سرعت منافی وقار دور باشد.', 66, NULL, '{"{\"answer\": \"برای راست بروید \", \"isCorrect\": false}","{\"answer\": \"در راه عجله نکنید \", \"isCorrect\": false}","{\"answer\": \"قصد راه رفتن را نمودند\", \"isCorrect\": false}","{\"answer\": \"در راه رفتنت جانب اعتدال را بگیر\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '637fa143-4461-4b4a-8af1-f8d0ffdb041d', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای درست کلمه ( واسبغ ) چیست ؟', NULL, 'چنانچه در سوره لقمان کلمه وَاَسبَغَ به معنی کامل ساخت آمده است.', 66, NULL, '{"{\"answer\": \"ناکامل ساخت \", \"isCorrect\": false}","{\"answer\": \"نا تکمیل بود \", \"isCorrect\": false}","{\"answer\": \"2 و 3 درست است \", \"isCorrect\": false}","{\"answer\": \"کامل ساخت \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '48dcd8f4-0709-4263-848a-fdff524d16f3', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('وطن عزیز ما گهواره پرورش عده زیادی از قرآن شناسان مامور تفسیر قرآن کریم است، از جمله آنان ؟', 'خواجه عبدالله انصاری در سال 396 در هرات به دنیا آمد و درسال 481 از دنیا رفت.', 'وطن عزیز ما افغانستان با سابقه درخشان و پر افتخار تاریخی و فکری گهواره پرورش عده زیادی از قران شناسان و علمای نامدار تفسیر قرآن کریم است که از جمله انان میتوان خواجه عبدالله انصاری هروی متوفای سال ۴۸۱ ه، امام فخرالدین رازی متوفای سال ۶۰۶ ه، مولانا مراد علی کاموی متوفای ۱۲۹۴ه را نام گرفت. ', 2, NULL, '{"{\"answer\": \"شیخ اسعد سوری است \", \"isCorrect\": false}","{\"answer\": \"ملا مشک عالم \", \"isCorrect\": false}","{\"answer\": \"سید جمال الدین افغلنی است \", \"isCorrect\": false}","{\"answer\": \"خواجه عبد الله انصاری \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '7b2101cc-0676-42f6-90f3-e39f59e589c1', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای دقیق کلمه ( ولا تصعیر خدک ) چیست ؟', NULL, 'لقمان حکیم به فرزند خود توصیه کرد که در هنگام راه رفتن از تکبر و تبخیر دوری کن زیرا که خداوند هیچ انسان متکبری را دوست ندارد.', 66, NULL, '{"{\"answer\": \"به قصد تکبر روی خود را بگردان \", \"isCorrect\": false}","{\"answer\": \"غیبت نکن \", \"isCorrect\": false}","{\"answer\": \"به قصد تصعیر کار را به انجام برسان\", \"isCorrect\": false}","{\"answer\": \"به قصد تکبر روی خود را مگردان \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '55b3bde1-8fb3-4591-8d33-468c14e9f938', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('درین آیت کریمه ( .... ظهرة و باطنةً وَ من النّاسِ من یُجدِلُ فی الله بغیر علم ولا هدًی ولا کتبٍ مُّنیر ) معنای دقیق ( ظهرة و با طنة ) چیست ؟', NULL, 'قسمی که لقمان حکیم می فرماید: بر انسان ها است تا در مقابل نعمت های ظاهری و معنوی خداوند متعال او را شکر گذار باشند.', 66, NULL, '{"{\"answer\": \"ظاهری محسوس و با تکبر دیدن \", \"isCorrect\": false}","{\"answer\": \"معنوی غیر محسوس و بدون ظاهری \", \"isCorrect\": false}","{\"answer\": \"ظاهری و بدون باطن\", \"isCorrect\": false}","{\"answer\": \"ظاهری محسوس و معنوی غیر محسوس\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', '1957b30f-cade-406b-bef2-0b326e6afcec', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای دقیق کلمه ( و اغضض من صوتک ) چیست ؟', NULL, 'مسلمان باید از بلند نمودن آواز بیش از حد خودداری کند زیرا که آواز خوب و گوارا همان است که در میان خفت و شدت باشد.', 66, NULL, '{"{\"answer\": \"آواز خود را کم کن \", \"isCorrect\": false}","{\"answer\": \"آواز خود را بلند نما \", \"isCorrect\": false}","{\"answer\": \"آواز خود را پایین گردان \", \"isCorrect\": false}","{\"answer\": \"آواز خود را آرام بدار \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'fe5db72d-009d-44eb-ab09-62a8e51bf2ff', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('در نصایح لقمان حکیم کلمه ( مرحاً ) چی معنا دارد ؟', NULL, 'لقمان حکیم به فرزند خود توصیه کرد که در هنگام راه رفتن از تکبر و تبخیر دوری کن زیرا که خداوند هیچ انسان متکبری را دوست ندارد.', 66, NULL, '{"{\"answer\": \"بدون تکبر و غرور\", \"isCorrect\": false}","{\"answer\": \"با زور و قوت \", \"isCorrect\": false}","{\"answer\": \"به قصد تکبر \", \"isCorrect\": false}","{\"answer\": \"با تکبر و غرور\", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'd2f41864-edfb-432a-977e-aef38c1670e8', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
	('معنای دقیق کلمه ( عزم الامور ) چیست ؟', NULL, 'چنانچه در سوره لقمان کلمه عَزمِ الاُمُورِ به معنی امور سترگ و برجسته ساخت آمده است.', 66, NULL, '{"{\"answer\": \"امور آسان و مشکل \", \"isCorrect\": false}","{\"answer\": \"امور خانه \", \"isCorrect\": false}","{\"answer\": \"امور دنیا\", \"isCorrect\": false}","{\"answer\": \"امور سترگ و برجسته \", \"isCorrect\": true}"}', 'built-in', NULL, '2025-06-23 09:21:30.728508+00', '2025-06-23 09:21:46.81689+00', 'fed96cd3-36c9-4de5-8aef-216d5f5c33d1', '091aeffc-30d1-40d5-98b0-cc77a695b840', 'a9fee42a-f464-48bc-aae9-8514edf8874a'),
