INSERT INTO "public"."libraries" ("title", "desc", "file_path", "uri", "created_at", "updated_at", "id", "category_id", "subject_id", "book_id", "grade_id") VALUES
	('دکوپاژ', 'اگرچه بسیاری از کسانی که به سینما می روند و یا تلوزیون تماشا می کنند سواد خواندن و نوشتن ندارند، اما می توانند زبان گویای تصویر را دریابند و این فیلمساز و سازنده برنامه تلویونی است که با زبان تصویر، آن چه را که می خواهد در ذهن و دل تماشاگر جای می دهد. و این ارتباط وقتی قرین توفیق است که فیلمساز با کاربرد زبان فیلم و مفاهیم تصویری هرچه بیشتر آشنا باشد.
دقت در تماشای انواع فیلم ها و برنامه های تلوزیونی، مطالعات مستمر و پیگیر، کسب مهارت های لازم و آموزش کامل فنون فیلم سازی ما را در مسیر گام نهادن در عرصه هنر سینما یاری خواهد کرد و هدف این کتاب جز این نسیت.', 'std_213', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/std_213.pdf', '2025-06-23 09:25:38.508511+00', '2026-06-19 19:21:02.816756+00', 'd6b5ae40-61fc-4edd-b410-265457eec5a5', '48838524-7374-4331-8903-2cd954055d4b', NULL, NULL, NULL),
	('چهل سالگی', 'رمان <<40 سالگی>> نوشته ناهید طباطبایی داستان بلندی از عشق و زندگی و دلدادگی در 40 سالگی است. آلاله دانشجوی موسیقی عاشق همکلاسی خود هرمز می شود، هرمز برای ادامه تحصیلات خود به خارج می رود. آلاله با شخص دیگری به نام فرهاد ازدواج می کند. بعد از 20 سال هرمز به ایران بر می گردد و آلاله به عنوان مدیر برنامه های هرمز مشغول به وظیفه می شود.  احساسات سرکوب شده در طی بیست سال دوباره در آلاله زنده می شود....', 'std_354', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/std_354.pdf', '2025-06-23 09:25:38.508511+00', '2026-06-19 20:42:29.943046+00', '94e56636-f24e-451c-a33a-47bda53539a6', '48838524-7374-4331-8903-2cd954055d4b', NULL, NULL, NULL),
	('هری پاتر و جام آتش', 'جی کی رولینگ خالق داستان های جذاب و خواندنی هری پاتر، کسی است که با استفاده از مفاهیمی مثل جادوگری و خلق اشیا شگفت انگیز توانسته تصویر بهتری از جادو در ذهن بشر خلق کند و در عین حال داستان هایی بسیار جذاب و خواندنی که مورد علاقه بیشتر مردم است را بیافریند. در داستان های هری پاتر دیگر جادو همیشه یک عمل منفی و ناشایست نیست و جادوگران می توانند شخصیت های مثبت هم داشته باشند. در این داستان ها هری پاتر به عنوان یک جادوگر در وسط راه آموزش قرار دارد. او می خواهد که یک جادوگر 14 ساله معمولی باشد اما خود هری پاتر اصلا معمولی نیست. حتی در چوکات جادوگری و در شرایط او این تفاوت می تواند برای او کشنده باشد.', 'std_392', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/std_392.pdf', '2025-06-23 09:25:38.508511+00', '2026-06-19 21:06:02.132273+00', '03fc5b0b-f693-4fa3-b483-7d658a1efb00', '48838524-7374-4331-8903-2cd954055d4b', NULL, NULL, NULL),
	('حالات تعادل در اجسام و پایداری(Types mechanical Equilibrium)', NULL, 'aux_lib_grd11_phs_7', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/aux_lib_grd11_phs_7.pdf', '2025-06-23 09:25:38.508511+00', '2025-06-23 09:25:55.099549+00', 'd690369a-d167-4948-a094-de3499ff6799', '9e062cba-47c7-4491-a51b-a894348103e8', NULL, '2b87a5cc-20ab-4a7b-a823-763ee3da389d', 'cba94f01-9816-47bb-a8ad-9100133ab6f6'),
	('برآورد نفوس افغانستان در سال 1399', 'اداره ملی احصائیه و معلومات در افغانستان مسرت دارد که نشریه برآورد نفوس سال از 1399 را به لسان های دری و پشتو و انگلیسی به نشر می رساند. امید است که این نشریه بخشی از نیازمندی های پالیسی سازان ، تصمیم گیرندگان و محققان را برآورده سازد.', 'aux_lib_gen_hst_10', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/aux_lib_gen_hst_10.pdf', '2025-06-23 09:25:38.508511+00', '2025-06-23 09:25:55.099549+00', 'dfbe1a7c-8699-460e-8028-32f951501854', '9e062cba-47c7-4491-a51b-a894348103e8', 'caeb4df7-af56-4d76-8396-0f5f14edd74e', NULL, NULL),
	('سرعت تعامل کیمیاوی', NULL, 'aux_lib_grd11_chm_2', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/aux_lib_grd11_chm_2.pdf', '2025-06-23 09:25:38.508511+00', '2025-06-23 09:25:55.099549+00', '41b8a301-a56a-4ad8-a596-2e057243ce46', '9e062cba-47c7-4491-a51b-a894348103e8', NULL, '44cdff31-b80f-46c6-bca1-5300913e7c71', 'cba94f01-9816-47bb-a8ad-9100133ab6f6'),
