	('برق و مقناطیس (آهن‌ربا)', NULL, 'aux_lib_grd10_phs_4', 'https://storage.googleapis.com/abzarkankorv2.firebasestorage.app/libraries/aux_lib_grd10_phs_4.pdf', '2025-06-23 09:25:38.508511+00', '2025-06-23 09:25:55.099549+00', '9f4b94da-1ffc-4bec-aa36-155aa76dd220', '9e062cba-47c7-4491-a51b-a894348103e8', NULL, '836e0039-81d6-4b5d-a26a-2cef99c64eaf', '091aeffc-30d1-40d5-98b0-cc77a695b840'),
