RESET ALL;

-- Rows above were inserted with session_replication_role = replica, so the
-- generate_slug trigger never fired for them and slug-based detail page
-- URLs (courses aside — sample_courses.sql sets slug explicitly) would 404.
-- Backfill any NULL slugs the same way the trigger would, collision suffix
-- included, so local dev matches how real inserts behave.
do $$
declare
  r record;
  base_slug text;
  candidate_slug text;
  slug_taken boolean;
begin
  for r in
    select id, title as label, 'quizzes' as tbl from public.quizzes where slug is null
    union all
    select id, title, 'libraries' from public.libraries where slug is null
    union all
    select id, name, 'decks' from public.decks where slug is null
  loop
    base_slug := public.slugify(r.label);
    candidate_slug := base_slug;
    loop
      execute format('select exists(select 1 from public.%I where slug = $1)', r.tbl)
        into slug_taken using candidate_slug;
      exit when not slug_taken;
      candidate_slug := base_slug || '-' || floor(random() * 9000 + 1000)::int;
    end loop;
    execute format('update public.%I set slug = $1 where id = $2', r.tbl)
      using candidate_slug, r.id;
